--!nocheck
--[[
	Pink UI Library
	Single file. Load it with loadstring / require and call Pink:Window { ... }.
	See Example.lua for every element.
]]

local Pink = {
	Flags = {},
	Options = {},
	Folder = "Pink",
	-- The embedded pixel font is drawn on a 12px em. TextSize starts at 12 and is corrected once the
	-- font loads (Roblox draws custom fonts one pixel larger than TextSize, so in game this becomes 11).
	TextSize = 12,
	-- LineHeight for wrapped labels; set with TextSize when the real glyph size is detected.
	LineHeight = 1,
	-- Rows between the top of a top-aligned label and the top of its tallest letters (l, d, h).
	GlyphOffset = 1,
	CapHeight = 8,
	Fonts = nil,
	-- Style, direction and speed drive the menu fade and notifications. Controls (toggles, dropdowns,
	-- groups) use a short ease-out scaled from Speed, which is how the original feels.
	Tweening = { Style = "Exponential", Direction = "InOut", Speed = 0.4 },
	ToggleKey = nil,
	Open = true,
	Windows = {},
	Connections = {},
	Unloaded = false,
}

Pink.Theme = {
	Accent = Color3.fromRGB(185, 97, 133),
	Outline = Color3.fromRGB(0, 0, 0),
	SectionBackground = Color3.fromRGB(31, 31, 31),
	OtherBackground = Color3.fromRGB(21, 21, 21),
	Inline = Color3.fromRGB(38, 38, 38),
	HighContrast = Color3.fromRGB(30, 30, 30),
	LowContrast = Color3.fromRGB(22, 22, 22),
	Unselected = Color3.fromRGB(178, 178, 178),
	TextColor = Color3.fromRGB(255, 255, 255),
}
Pink.ThemeOrder = { "Accent", "Outline", "SectionBackground", "OtherBackground", "Inline", "HighContrast", "LowContrast", "Unselected", "TextColor" }
Pink.ThemeNames = {
	Accent = "Accent", Outline = "Outline", SectionBackground = "Section Background", OtherBackground = "Other Background",
	Inline = "Inline", HighContrast = "High Contrast", LowContrast = "Low Contrast", Unselected = "Unselected", TextColor = "Text Color",
}

-- Services ------------------------------------------------------------------
local cloneref = cloneref or function(object) return object end
local function getService(name)
	local ok, service = pcall(function() return game:GetService(name) end)
	return ok and service and cloneref(service) or nil
end

local Players = getService("Players")
local TweenService = getService("TweenService")
local UserInputService = getService("UserInputService")
local RunService = getService("RunService")
local HttpService = getService("HttpService")
local CoreGui = getService("CoreGui")
local LocalPlayer = Players and Players.LocalPlayer

-- Small helpers -------------------------------------------------------------
local UDim2_new, fromOffset = UDim2.new, UDim2.fromOffset
local floor, clamp, max, min = math.floor, math.clamp, math.max, math.min

local function connect(signal, fn)
	local connection = signal:Connect(fn)
	table.insert(Pink.Connections, connection)
	return connection
end

local function create(class, props, children)
	local inst = Instance.new(class)
	local parent
	for key, value in props or {} do
		if key == "Parent" then parent = value else inst[key] = value end
	end
	for _, child in children or {} do child.Parent = inst end
	if inst:IsA("GuiObject") then inst.BorderSizePixel = 0 end
	if parent then inst.Parent = parent end
	return inst
end

local function lerpColor(a, b, t)
	return Color3.new(a.R + (b.R - a.R) * t, a.G + (b.G - a.G) * t, a.B + (b.B - a.B) * t)
end

local function toHex(color)
	return string.format("%02X%02X%02X", floor(color.R * 255 + 0.5), floor(color.G * 255 + 0.5), floor(color.B * 255 + 0.5))
end

local function fromHex(hex)
	hex = tostring(hex):gsub("#", "")
	if #hex ~= 6 then return nil end
	local r, g, b = tonumber(hex:sub(1, 2), 16), tonumber(hex:sub(3, 4), 16), tonumber(hex:sub(5, 6), 16)
	if not (r and g and b) then return nil end
	return Color3.fromRGB(r, g, b)
end

local function toHSV(color)
	local r, g, b = color.R, color.G, color.B
	local hi, lo = max(r, g, b), min(r, g, b)
	local delta = hi - lo
	local h = 0
	if delta > 0 then
		if hi == r then h = ((g - b) / delta) % 6
		elseif hi == g then h = (b - r) / delta + 2
		else h = (r - g) / delta + 4 end
		h /= 6
	end
	return h, hi == 0 and 0 or delta / hi, hi
end

local function round(value, step)
	step = step or 1
	return floor(value / step + 0.5) * step
end

local function decimalsOf(step)
	local text = tostring(step)
	local dot = text:find("%.")
	return dot and #text - dot or 0
end

-- Themed painting ------------------------------------------------------------
-- A painter runs now and again whenever a theme colour changes.
local painters = {}
local function paint(fn)
	table.insert(painters, fn)
	fn(Pink.Theme)
	return fn
end

local themeListeners = {}
function Pink:SetTheme(key, color)
	if self.Theme[key] == nil then return end
	self.Theme[key] = color
	for _, fn in painters do pcall(fn, self.Theme) end
	for _, fn in themeListeners do pcall(fn, key, color) end
end

local function accentSequence(theme)
	return ColorSequence.new(theme.Accent, lerpColor(theme.Accent, Color3.fromRGB(70, 80, 75), 0.55))
end

-- Tweening ------------------------------------------------------------------
function Pink:TweenInfo(time)
	local style = Enum.EasingStyle[self.Tweening.Style] or Enum.EasingStyle.Exponential
	local direction = Enum.EasingDirection[self.Tweening.Direction] or Enum.EasingDirection.InOut
	return TweenInfo.new(time or self.Tweening.Speed, style, direction)
end

-- Short ease-out used by every control (about 0.12s at the default speed).
local function microTime()
	return Pink.Tweening.Speed * 0.3
end

-- Running tweens per instance and property. An instant set must cancel them, or a tween that is
-- still playing (a hover fade, say) overwrites the new value on its next frame.
local running = setmetatable({}, { __mode = "k" })
local function play(inst, goals, info)
	local active = running[inst]
	if not TweenService or info.Time <= 0 then
		for key, value in goals do
			if active and active[key] then
				active[key]:Cancel()
				active[key] = nil
			end
			inst[key] = value
		end
		return nil
	end
	local t = TweenService:Create(inst, info, goals)
	if not active then
		active = {}
		running[inst] = active
	end
	for key in goals do active[key] = t end
	t:Play()
	return t
end

-- Controls: quick ease-out. `time` 0 sets instantly.
local function tween(inst, goals, time)
	return play(inst, goals, TweenInfo.new(time or microTime(), Enum.EasingStyle.Quad, Enum.EasingDirection.Out))
end

-- Larger transitions (menu fade, notifications) follow the Appearance settings.
local function styledTween(inst, goals, time)
	return play(inst, goals, Pink:TweenInfo(time))
end

-- Frame-driven animation for layout changes (heights), so lists re-flow every frame.
local animations = setmetatable({}, { __mode = "k" })
local function animate(key, duration, step, done)
	local token = {}
	animations[key] = token
	if duration <= 0 or not RunService then
		step(1)
		if done then done() end
		return
	end
	local elapsed = 0
	step(0)
	local connection
	connection = RunService.Heartbeat:Connect(function(dt)
		if animations[key] ~= token then connection:Disconnect() return end
		elapsed += dt
		local alpha = math.min(elapsed / duration, 1)
		step(1 - (1 - alpha) * (1 - alpha))
		if alpha >= 1 then
			connection:Disconnect()
			animations[key] = nil
			if done then done() end
		end
	end)
end


-- Fading without CanvasGroups ------------------------------------------------------
-- CanvasGroups re-rasterise their contents and blur pixel text, so fades drive each object's own
-- transparency instead. `rest` remembers the fully visible value of every faded property; it is
-- recorded once when an object first fades and updated by setRest when a control changes its own look.
local fadeProps = {
	Frame = { "BackgroundTransparency" },
	ScrollingFrame = { "BackgroundTransparency" },
	TextLabel = { "BackgroundTransparency", "TextTransparency" },
	TextButton = { "BackgroundTransparency", "TextTransparency" },
	TextBox = { "BackgroundTransparency", "TextTransparency" },
	ImageLabel = { "BackgroundTransparency", "ImageTransparency" },
	ImageButton = { "BackgroundTransparency", "ImageTransparency" },
	UIStroke = { "Transparency" },
}
local rest = setmetatable({}, { __mode = "k" })
local fadeAlpha = setmetatable({}, { __mode = "k" }) -- root -> 0 (visible) .. 1 (hidden)
local fadeRootOf = setmetatable({}, { __mode = "k" })

local function easeStyled(alpha)
	local ok, value = pcall(function()
		return TweenService:GetValue(alpha, Enum.EasingStyle[Pink.Tweening.Style], Enum.EasingDirection[Pink.Tweening.Direction])
	end)
	if ok and type(value) == "number" then return value end
	return 1 - (1 - alpha) * (1 - alpha)
end

local function fadeTargets(root)
	local list = {}
	local function add(inst)
		local props = fadeProps[inst.ClassName]
		if not props then return end
		local saved = rest[inst]
		if not saved then
			saved = {}
			for _, prop in props do saved[prop] = inst[prop] end
			rest[inst] = saved
		end
		fadeRootOf[inst] = root
		table.insert(list, inst)
	end
	add(root)
	for _, inst in root:GetDescendants() do add(inst) end
	return list
end

local function applyFade(list, alpha)
	for _, inst in list do
		local saved = rest[inst]
		if saved and inst.Parent then
			for prop, value in saved do inst[prop] = value + (1 - value) * alpha end
		end
	end
end

-- Fades `root` and everything under it to hidden (true) or shown (false).
local function fadeTree(root, hide, duration, done)
	local list = fadeTargets(root)
	local from = fadeAlpha[root] or (hide and 0 or 1)
	local to = hide and 1 or 0
	animate(root, duration, function(alpha)
		local value = from + (to - from) * easeStyled(alpha)
		fadeAlpha[root] = value
		applyFade(list, value)
	end, function()
		if not hide then
			-- Fully visible again: forget the snapshot so later restyling is read fresh next time.
			for _, inst in list do rest[inst] = nil end
			fadeAlpha[root] = nil
		end
		if done then done() end
	end)
end

-- Controls call this for transparency they animate themselves (toggle fills), so a fade in
-- progress or a hidden menu still comes back to the right value.
local function setRest(inst, prop, value, time)
	local saved = rest[inst]
	if saved and saved[prop] ~= nil then
		saved[prop] = value
		local alpha = fadeAlpha[fadeRootOf[inst]] or 0
		inst[prop] = value + (1 - value) * alpha
		return
	end
	tween(inst, { [prop] = value }, time)
end

-- Fonts ---------------------------------------------------------------------
-- BEGIN EMBEDDED FONTS (generated by tools/build_font.py)
local FONT_REGULAR = ""
local FONT_BOLD = ""
-- END EMBEDDED FONTS

local function base64Decode(data)
	local ok, out = pcall(function()
		if crypt and crypt.base64decode then return crypt.base64decode(data) end
		if crypt and crypt.base64 and crypt.base64.decode then return crypt.base64.decode(data) end
		if base64_decode then return base64_decode(data) end
		if base64 and base64.decode then return base64.decode(data) end
		error("no native decoder")
	end)
	if ok and type(out) == "string" and #out > 0 then return out end
	local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local lookup = {}
	for i = 1, 64 do lookup[string.byte(alphabet, i)] = i - 1 end
	local bytes, n = {}, 0
	local bits, value = 0, 0
	for i = 1, #data do
		local v = lookup[string.byte(data, i)]
		if v then
			value = value * 64 + v
			bits += 6
			if bits >= 8 then
				bits -= 8
				local divisor = 2 ^ bits
				n += 1
				bytes[n] = string.char(math.floor(value / divisor) % 256)
				value %= divisor
			end
		end
	end
	return table.concat(bytes)
end
Pink._base64Decode = base64Decode

-- Writes the embedded fonts and returns Font objects.
function Pink:_installFonts()
	local fonts
	pcall(function()
		assert(writefile and isfile and getcustomasset and makefolder and isfolder and FONT_REGULAR ~= "")
		local folder = self.Folder .. "/fonts"
		if not isfolder(self.Folder) then makefolder(self.Folder) end
		if not isfolder(folder) then makefolder(folder) end
		-- Versioned names: executors cache custom assets by path.
		local version = "v4"
		local faces = {}
		for _, face in { { "Regular", 400, FONT_REGULAR }, { "Bold", 700, FONT_BOLD } } do
			local path = folder .. "/PinkPixel-" .. face[1] .. "-" .. version .. ".ttf"
			if not isfile(path) then writefile(path, base64Decode(face[3])) end
			table.insert(faces, { name = face[1], weight = face[2], style = "normal", assetId = getcustomasset(path) })
		end
		local familyPath = folder .. "/PinkPixel-" .. version .. ".json"
		writefile(familyPath, HttpService:JSONEncode({ name = "PinkPixel", faces = faces }))
		local family = getcustomasset(familyPath)
		fonts = {
			Regular = Font.new(family, Enum.FontWeight.Regular),
			Bold = Font.new(family, Enum.FontWeight.Bold),
		}
		self._customFont = true
	end)
	return fonts
end

function Pink:LoadFonts()
	if self.Fonts then return self.Fonts end
	self.Fonts = self:_installFonts() or {
		Regular = Font.new("rbxasset://fonts/families/Arial.json", Enum.FontWeight.Regular),
		Bold = Font.new("rbxasset://fonts/families/Arial.json", Enum.FontWeight.Bold),
	}
	return self.Fonts
end

-- Every label made by text() (value: true when it wraps onto several lines).
local allText = setmetatable({}, { __mode = "k" })

-- Text size detection ---------------------------------------------------------------
-- glyphs out one pixel larger than TextSize (TextSize 11 matches the 12px design exactly) while the
-- line box stays TextSize tall. Rather than hard-code that, whole sizes are probed and the one whose
-- widths equal the design widths is used; wrapped labels get a LineHeight that restores 12px lines.
local DESIGN = { { string.rep("W", 20), 200 }, { string.rep("i", 20), 40 }, { "Pink Pixel Probe", 75 } }
function Pink:_detectTextSize(gui)
	if not self._customFont then return end -- fallback font: keep the defaults
	local candidates = { 12, 11, 13, 10 }
	local probes = {}
	for _, size in candidates do
		for index, sample in DESIGN do
			table.insert(probes, create("TextLabel", {
				Name = "PinkProbe", BackgroundTransparency = 1, TextTransparency = 1, Text = sample[1],
				FontFace = self.Fonts.Regular, TextSize = size, Position = fromOffset(-10000, -10000), Size = fromOffset(2000, 100), Parent = gui,
			}))
			probes[#probes].Name = "PinkProbe_" .. size .. "_" .. index
		end
	end
	local pending = false
	local function apply()
		pending = false
		for c, size in candidates do
			local exact, lineHeight = true, nil
			for index, sample in DESIGN do
				local bounds = probes[(c - 1) * #DESIGN + index].TextBounds
				if math.abs(bounds.X - sample[2]) > 1 then exact = false end
				lineHeight = bounds.Y
			end
			if exact and lineHeight and lineHeight > 0 then
				local line = 12 / math.floor(lineHeight + 0.5)
				if size == self.TextSize and line == self.LineHeight then return end
				self.TextSize, self.LineHeight = size, line
				for label, wrapped in allText do
					if label.Parent then
						label.TextSize = size
						if wrapped then label.LineHeight = line end
					end
				end
				return
			end
		end
	end
	local function schedule()
		if pending then return end
		pending = true
		task.delay(0.1, apply)
	end
	for _, probe in probes do probe:GetPropertyChangedSignal("TextBounds"):Connect(schedule) end
	schedule()
end

-- Layout functions that depend on a parent's width; a window resize runs them all again.
local relayouts = setmetatable({}, { __mode = "k" })

-- Text ----------------------------------------------------------------------------
-- Re-centring functions for whole-pixel centred labels, run again whenever a parent is resized by code.
local centerers = setmetatable({}, { __mode = "k" })
local function recenter(label) local fn = centerers[label] if fn then fn() end end

-- Custom fonts finish loading after a label exists, so anything sized from TextBounds re-runs when they change.
local function onBounds(label, fn)
	fn()
	label:GetPropertyChangedSignal("TextBounds"):Connect(fn)
end

local function text(parent, props)
	local label = create(props.Button and "TextButton" or (props.Box and "TextBox" or "TextLabel"), {
		Name = props.Name or "Text",
		BackgroundTransparency = 1,
		FontFace = props.Bold and Pink.Fonts.Bold or Pink.Fonts.Regular,
		TextSize = props.TextSize or Pink.TextSize,
		Text = props.Text or "",
		TextXAlignment = props.XAlign or Enum.TextXAlignment.Left,
		TextYAlignment = props.YAlign or Enum.TextYAlignment.Top,
		Position = props.Position or fromOffset(0, 0),
		Size = props.Size or UDim2_new(1, 0, 0, 12),
		TextWrapped = props.Wrapped or false,
		TextTruncate = props.Truncate and Enum.TextTruncate.AtEnd or Enum.TextTruncate.None,
		ZIndex = props.ZIndex or 1,
		Parent = parent,
	})
	if props.LineHeight then label.LineHeight = props.LineHeight end
	if not props.TextSize then
		allText[label] = props.Wrapped == true
		if props.Wrapped then label.LineHeight = Pink.LineHeight end
	end
	if props.Button then label.AutoButtonColor = false end
	if props.Box then
		label.ClearTextOnFocus = false
		label.PlaceholderText = props.Placeholder or ""
		paint(function(theme) label.PlaceholderColor3 = lerpColor(theme.Unselected, theme.Outline, 0.35) end)
	end
	local stroke = create("UIStroke", { Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual, Parent = label })
	pcall(function() stroke.LineJoinMode = Enum.LineJoinMode.Miter end)
	paint(function(theme) stroke.Color = theme.Outline end)
	local colorKey = props.Color
	if colorKey == nil then colorKey = "TextColor" end
	if colorKey ~= false then
		paint(function(theme) label.TextColor3 = theme[colorKey] end)
	end
	if props.CenterX then
		-- Whole-pixel centring: Roblox's Center alignment lands on half pixels when the spare
		-- width is odd, which blurs a pixel font, so the label is left-aligned at a floored offset.
		label.TextXAlignment = Enum.TextXAlignment.Left
		local function place()
			local width = parent.AbsoluteSize.X
			if width <= 0 then return end
			local x = math.floor((width - label.TextBounds.X) / 2)
			label.Position = UDim2_new(0, x, label.Position.Y.Scale, label.Position.Y.Offset)
		end
		label.Size = UDim2_new(0, 1000, label.Size.Y.Scale, label.Size.Y.Offset)
		centerers[label] = place
		onBounds(label, place)
		parent:GetPropertyChangedSignal("AbsoluteSize"):Connect(place)
	end
	return label
end

-- Top of a label whose capitals sit centred in a box `height` tall.
local function centerY(height)
	return math.floor((height - Pink.CapHeight) / 2) - Pink.GlyphOffset
end

-- A text box only as tall as its line, plus a click target over the whole control.
local function focusOnClick(container, box)
	local hit = create("TextButton", { Name = "Focus", BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Size = UDim2_new(1, 0, 1, 0), ZIndex = box.ZIndex - 1, Parent = container })
	hit.MouseButton1Click:Connect(function() box:CaptureFocus() end)
	return hit
end

-- Inline frames whose colour an element drives itself (toggles).
local customInline = setmetatable({}, { __mode = "k" })

-- Outline + inline + fill, the bevelled box every control uses.
-- fill: "element" (vertical gradient), "reverse", "none" (caller paints it), or a theme key.
local function box(parent, props)
	local outer = create("Frame", {
		Name = props.Name or "Box",
		Position = props.Position or fromOffset(0, 0),
		Size = props.Size or UDim2_new(1, 0, 0, 19),
		ZIndex = props.ZIndex or 1,
		Parent = parent,
	})
	local inline = create("Frame", { Name = "Inline", Position = fromOffset(1, 1), Size = UDim2_new(1, -2, 1, -2), ZIndex = outer.ZIndex, Parent = outer })
	local fill = create("Frame", { Name = "Fill", Position = fromOffset(1, 1), Size = UDim2_new(1, -2, 1, -2), ZIndex = outer.ZIndex, Parent = inline })
	local kind = props.Fill or "element"
	local gradient
	if kind == "element" or kind == "reverse" then
		fill.BackgroundColor3 = Color3.new(1, 1, 1)
		gradient = create("UIGradient", { Rotation = 90, Parent = fill })
	end
	paint(function(theme)
		outer.BackgroundColor3 = theme.Outline
		if not customInline[inline] then inline.BackgroundColor3 = theme.Inline end
		if gradient then
			local a, b = theme.LowContrast, theme.HighContrast
			if kind == "reverse" then a, b = lerpColor(theme.HighContrast, theme.Inline, 0.5), theme.LowContrast end
			gradient.Color = ColorSequence.new(a, b)
		elseif kind ~= "none" then
			fill.BackgroundColor3 = theme[kind]
		end
	end)
	return outer, inline, fill
end

local function accentFill(parent, props)
	local frame = create("Frame", {
		Name = props.Name or "Accent",
		BackgroundColor3 = Color3.new(1, 1, 1),
		Position = props.Position or fromOffset(0, 0),
		Size = props.Size or UDim2_new(1, 0, 1, 0),
		ZIndex = props.ZIndex or 1,
		Parent = parent,
	})
	local gradient = create("UIGradient", { Rotation = 90, Parent = frame })
	paint(function(theme) gradient.Color = accentSequence(theme) end)
	return frame
end

-- Input helpers ---------------------------------------------------------------
local function mousePosition()
	local location = UserInputService:GetMouseLocation()
	local ok, offset = pcall(function() return Pink.Gui.AbsolutePosition end)
	if ok and typeof(offset) == "Vector2" then return location + offset end
	return location
end

local function toGui(absolute)
	local ok, offset = pcall(function() return Pink.Gui.AbsolutePosition end)
	if ok and typeof(offset) == "Vector2" then return absolute - offset end
	return absolute
end

local function isClick(input)
	return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end

local function inside(gui, point)
	local position, size = gui.AbsolutePosition, gui.AbsoluteSize
	return point.X >= position.X and point.X < position.X + size.X and point.Y >= position.Y and point.Y < position.Y + size.Y
end

-- Drags call move(position) while the button is held, then done().
local function beginDrag(move, done)
	move(mousePosition())
	local moved, ended
	moved = UserInputService.InputChanged:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
			move(mousePosition())
		end
	end)
	ended = UserInputService.InputEnded:Connect(function(input)
		if isClick(input) then
			moved:Disconnect()
			ended:Disconnect()
			if done then done() end
		end
	end)
end

local keyNames = {
	LeftShift = "LShift", RightShift = "RShift", LeftControl = "LCtrl", RightControl = "RCtrl", LeftAlt = "LAlt", RightAlt = "RAlt",
	Return = "Enter", Backspace = "Back", Zero = "0", One = "1", Two = "2", Three = "3", Four = "4", Five = "5", Six = "6", Seven = "7", Eight = "8", Nine = "9",
	MouseButton1 = "MB1", MouseButton2 = "MB2", MouseButton3 = "MB3", Insert = "Ins", Delete = "Del", PageUp = "PgUp", PageDown = "PgDn",
	CapsLock = "Caps", Escape = "Esc",
}
local function keyName(key)
	if key == nil then return "None" end
	return keyNames[key.Name] or key.Name
end

-- Overlay popups (dropdown lists, colour pickers) close when another opens.
local activePopup
local function closePopup()
	if activePopup then
		local popup = activePopup
		activePopup = nil
		popup:Close()
	end
end

-- Layout constants measured from the reference ---------------------------------
local PAD = 5           -- gap between elements in a section
local BOX_H = 19        -- standard control height
local TOGGLE_H = 16
local SLIDER_H = 34     -- label + bar + 2px tail
local SLIDER_BAR_Y = 13
local DROPDOWN_H = 34
local DROPDOWN_BOX_Y = 15
local KEYBIND_H = 20
local COLOR_H = 18
local TEXTBOX_H = 20
local ROW_H = 17        -- list rows
local SECTION_TOP = 32  -- first element below a section's top edge
local SECTION_BODY_Y = 27 -- scrolling area starts just under the section title
local SECTION_BOTTOM = 8

local function glyph(y) return y - Pink.GlyphOffset end

-- Containers (sections and dependency groups) share every element constructor.
local Container = {}
Container.__index = Container

-- widthOffset: the container is its parent's width plus this many pixels.
local function newContainer(parentFrame, widthOffset, owner)
	local self = setmetatable({}, Container)
	self.WidthOffset = widthOffset or 0
	self.Owner = owner
	self.Items = {}
	-- Holders that carry their own leading gap (groups), so they can grow from zero smoothly.
	self.Flush = setmetatable({}, { __mode = "k" })
	self.Frame = create("Frame", {
		Name = "Container",
		BackgroundTransparency = 1,
		Size = UDim2_new(1, widthOffset or 0, 0, 0),
		Parent = parentFrame,
	})
	return self
end

-- Stacks visible holders top to bottom with PAD between them and returns the total height.
function Container:Layout()
	local y, first = 0, true
	for _, holder in self.Items do
		if holder.Visible then
			if not first and not self.Flush[holder] then y += PAD end
			holder.Position = fromOffset(0, y)
			y += holder.Size.Y.Offset
			first = false
		end
	end
	return y
end

function Container:ContentHeight()
	return self:Layout()
end

function Container:Resize()
	self.Frame.Size = UDim2_new(1, self.WidthOffset, 0, self:Layout())
	if self.Owner then self.Owner:Resize() end
end

function Container:_holder(height, name, after)
	local holder = create("Frame", {
		Name = name or "Element",
		BackgroundTransparency = 1,
		Size = UDim2_new(1, 0, 0, height),
		Parent = self.Frame,
	})
	local index = after and table.find(self.Items, after)
	if index then table.insert(self.Items, index + 1, holder) else table.insert(self.Items, holder) end
	self:Resize()
	return holder
end

local function register(element, options)
	if options.Flag then
		Pink.Flags[options.Flag] = element
		Pink.Options[options.Flag] = element
	end
	return element
end

local function fire(element, ...)
	for _, fn in element.Changed do task.spawn(fn, ...) end
	if element.Callback then task.spawn(element.Callback, ...) end
end

local function newElement(options)
	local element = { Changed = {}, Callback = options.Callback, Flag = options.Flag }
	function element:OnChanged(fn) table.insert(self.Changed, fn) return self end
	return element
end

-- Text label ------------------------------------------------------------------
function Container:Label(options)
	if type(options) == "string" then options = { Text = options } end
	local holder = self:_holder(13, "Label")
	local label = text(holder, {
		Text = options.Text or options.Name or "",
		Color = options.Color or "Unselected",
		Wrapped = true,
		Position = fromOffset(0, glyph(2)),
		Size = UDim2_new(1, 2, 0, 2000),
	})
	local element = newElement(options)
	element.Holder, element.Label = holder, label
	local function fit()
		local height = floor(label.TextBounds.Y) + 2
		if holder.Size.Y.Offset ~= height then
			holder.Size = UDim2_new(1, 0, 0, height)
			self:Resize()
		end
	end
	function element:Set(value)
		label.Text = value
	end
	onBounds(label, fit)
	relayouts[label] = fit
	return element
end

-- Dependency box ------------------------------------------------------------------
-- A container whose elements only show while its dependencies hold. It grows and shrinks with
-- an animation and pushes the rest of the section. Dependencies are { element, value } pairs:
-- a toggle with true/false, a dropdown with the option that must be selected.
function Container:DependencyBox(after)
	local container = self
	local holder = container:_holder(0, "Dependency", after)
	holder.ClipsDescendants = true
	holder.Visible = false
	container.Flush[holder] = true
	local group = newContainer(holder, 0, nil)
	group.Frame.Position = fromOffset(0, PAD)
	group.Holder = holder
	local shown = 0
	local function apply()
		local full = PAD + group:ContentHeight()
		holder.Size = UDim2_new(1, 0, 0, math.floor(full * shown + 0.5))
		holder.Visible = shown > 0
		container:Resize()
	end
	group.Owner = { Resize = function() if shown > 0 then apply() end end }
	function group:SetVisible(visible, instant)
		local from, to = shown, visible and 1 or 0
		if from == to then return end
		animate(holder, instant and 0 or microTime() * 1.2, function(alpha)
			shown = from + (to - from) * alpha
			apply()
		end)
	end
	function group:SetupDependencies(dependencies)
		local function holds()
			for _, dependency in dependencies do
				local element, want = dependency[1], dependency[2]
				local value = element.Value
				if type(value) == "table" and element.Multi then
					if value[want] ~= true then return false end
				elseif value ~= want then
					return false
				end
			end
			return true
		end
		for _, dependency in dependencies do dependency[1]:OnChanged(function() group:SetVisible(holds()) end) end
		group:SetVisible(holds(), true)
		return group
	end
	return group
end

-- Toggle ------------------------------------------------------------------------
function Container:Toggle(options)
	local container = self
	local holder = self:_holder(TOGGLE_H, "Toggle")
	local click = create("TextButton", { Name = "Click", BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Size = UDim2_new(1, 0, 1, 0), Parent = holder })
	local outer, inline = box(holder, { Size = fromOffset(16, 16) })
	local fill = accentFill(inline, { Position = fromOffset(1, 1), Size = UDim2_new(1, -2, 1, -2) })
	fill.BackgroundTransparency = 1
	local label = text(holder, { Text = options.Name or "Toggle", Color = false, Position = fromOffset(21, glyph(3)), Size = UDim2_new(1, -21, 0, 12) })
	local addons = create("Frame", { Name = "Addons", BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0), Position = UDim2_new(1, 0, 0, 0), Size = UDim2_new(0, 0, 1, 0), Parent = holder })
	create("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, HorizontalAlignment = Enum.HorizontalAlignment.Right, Padding = UDim.new(0, 5), SortOrder = Enum.SortOrder.LayoutOrder, Parent = addons })

	local element = newElement(options)
	element.Holder, element.Label, element.Type = holder, label, "Toggle"
	element.Value = options.Default == true
	element.Addons = {}

	local hovering = false
	local function render(instant)
		local theme = Pink.Theme
		local time = instant and 0 or nil
		setRest(fill, "BackgroundTransparency", element.Value and 0 or 1, time)
		tween(inline, { BackgroundColor3 = element.Value and lerpColor(theme.Accent, theme.Outline, 0.6) or theme.Inline }, time)
		tween(label, { TextColor3 = (element.Value or hovering) and theme.TextColor or theme.Unselected }, time)
	end
	customInline[inline] = true
	paint(function() render(true) end)

	function element:Set(value)
		value = value == true
		if value == self.Value then return end
		self.Value = value
		render()
		fire(self, value)
	end
	function element:Get() return self.Value end

	connect(click.MouseButton1Click, function() element:Set(not element.Value) end)
	connect(click.MouseEnter, function() hovering = true; render() end)
	connect(click.MouseLeave, function() hovering = false; render() end)

	-- Addons sit at the right edge of the row.
	function element:Colorpicker(opts)
		opts = opts or {}
		local picker = container:_colorSwatch(addons, opts)
		addons.Size = UDim2_new(0, #addons:GetChildren() * 28, 1, 0)
		table.insert(self.Addons, picker)
		return picker
	end
	element.ColorPicker = element.Colorpicker
	function element:Keybind(opts)
		opts = opts or {}
		local bind = container:_keyBox(addons, opts)
		table.insert(self.Addons, bind)
		return bind
	end
	-- Dependency box placed right under this toggle, shown while the toggle is on.
	function element:Group()
		if self.Dependent then return self.Dependent end
		local group = container:DependencyBox(holder)
		group:SetupDependencies({ { self, true } })
		self.Dependent = group
		return group
	end
	element.DependencyBox = element.Group

	render(true)
	return register(element, options)
end

-- Slider --------------------------------------------------------------------------
function Container:Slider(options)
	local holder = self:_holder(SLIDER_H, "Slider")
	text(holder, { Text = options.Name or "Slider", Color = "Unselected", Position = fromOffset(0, glyph(0)) })
	local outer, inline, boxFill = box(holder, { Position = fromOffset(0, SLIDER_BAR_Y), Size = UDim2_new(1, 0, 0, BOX_H) })
	local fill = create("Frame", { Name = "Rim", ClipsDescendants = true, Position = fromOffset(0, 0), Size = UDim2_new(0, 0, 1, 0), Parent = inline })
	paint(function(theme) fill.BackgroundColor3 = lerpColor(theme.Accent, theme.Outline, 0.6) end)
	accentFill(fill, { Position = fromOffset(1, 1), Size = UDim2_new(1, -1, 1, -2) })
	local valueText = text(outer, { Text = "", Color = "TextColor", CenterX = true, Position = fromOffset(0, centerY(BOX_H)), ZIndex = 2 })
	local click = create("TextButton", { Name = "Click", BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Size = UDim2_new(1, 0, 1, 0), ZIndex = 3, Parent = outer })

	local element = newElement(options)
	element.Holder, element.Type = holder, "Slider"
	element.Min, element.Max = options.Min or 0, options.Max or 100
	element.Step = options.Increment or options.Step or (options.Decimals and 10 ^ -options.Decimals) or 1
	element.Range = options.Range == true
	local places = decimalsOf(element.Step)

	local function format(value)
		if options.Format then return options.Format(value) end
		return string.format("%." .. places .. "f", value) .. (options.Suffix or "")
	end
	local function display()
		if element.Range then
			valueText.Text = format(element.Value[1]) .. " - " .. format(element.Value[2])
		else
			valueText.Text = format(element.Value)
		end
	end
	local function render(instant)
		local span = element.Max - element.Min
		local a, b
		if element.Range then
			a, b = (element.Value[1] - element.Min) / span, (element.Value[2] - element.Min) / span
		else
			a, b = 0, (element.Value - element.Min) / span
		end
		local goal = { Position = UDim2_new(a, 0, 0, 0), Size = UDim2_new(b - a, 0, 1, 0) }
		tween(fill, goal, instant and 0 or nil)
		display()
	end

	local function clean(value)
		return tonumber(string.format("%." .. places .. "f", clamp(round(value, element.Step), element.Min, element.Max)))
	end
	if element.Range then
		local default = options.Default or { element.Min, element.Max }
		element.Value = { clean(default[1]), clean(default[2]) }
	else
		element.Value = clean(options.Default or element.Min)
	end

	function element:Set(value, instant)
		if self.Range then
			value = { clean(value[1]), clean(value[2]) }
			if value[1] > value[2] then value[1], value[2] = value[2], value[1] end
			if value[1] == self.Value[1] and value[2] == self.Value[2] then return end
		else
			value = clean(value)
			if value == self.Value then return end
		end
		self.Value = value
		render(instant)
		fire(self, value)
	end
	function element:Get() return self.Value end
	function element:SetMax(value) self.Max = value; render(true) end
	function element:SetMin(value) self.Min = value; render(true) end

	local function valueAt(point)
		local pct = clamp((point.X - inline.AbsolutePosition.X) / inline.AbsoluteSize.X, 0, 1)
		return element.Min + (element.Max - element.Min) * pct
	end
	connect(click.InputBegan, function(input)
		if not isClick(input) then return end
		local handle
		if element.Range then
			local v = valueAt(mousePosition())
			handle = math.abs(v - element.Value[1]) <= math.abs(v - element.Value[2]) and 1 or 2
		end
		beginDrag(function(point)
			local v = valueAt(point)
			if element.Range then
				local pair = { element.Value[1], element.Value[2] }
				pair[handle] = v
				if handle == 1 and v > pair[2] then pair[1] = pair[2] end
				if handle == 2 and v < pair[1] then pair[2] = pair[1] end
				element:Set(pair)
			else
				element:Set(v)
			end
		end)
	end)

	render(true)
	return register(element, options)
end

-- Dropdown --------------------------------------------------------------------------
local function optionList(owner, options)
	-- Floating list on the overlay layer, above every window. It tweens open downwards inside a
	-- clipping frame; an optional search box filters the rows, which glide into their new slots
	-- while the list tweens to its new height.
	local ROW, GAP = 15, 3
	local searchable = options.Search ~= false
	local maxRows = options.MaxVisible or 8
	local list = { Open = false, Rows = {} }
	local group = create("Frame", { Name = "DropdownList", BackgroundTransparency = 1, ClipsDescendants = true, Visible = false, ZIndex = 50, Parent = Pink.Overlay })
	local searchHeight = searchable and (BOX_H + GAP) or 0

	local search
	if searchable then
		local searchOuter = box(group, { Name = "Search", Size = UDim2_new(1, 0, 0, BOX_H), Fill = "reverse", ZIndex = 50 })
		search = text(searchOuter, { Box = true, Placeholder = "Search...", Text = "", Color = "Unselected", Position = fromOffset(6, centerY(BOX_H)), Size = UDim2_new(1, -12, 0, 12), ZIndex = 52 })
		search.ClipsDescendants = true
		focusOnClick(searchOuter, search)
		connect(search.Focused, function() tween(search, { TextColor3 = Pink.Theme.TextColor }) end)
		connect(search.FocusLost, function() tween(search, { TextColor3 = Pink.Theme.Unselected }) end)
	end
	local outer, inline, fill = box(group, { Name = "Rows", Position = fromOffset(0, searchHeight), Size = UDim2_new(1, 0, 0, 8), Fill = "element", ZIndex = 50 })
	local scroll = create("ScrollingFrame", {
		Name = "Rows", BackgroundTransparency = 1, Position = fromOffset(0, 2), Size = UDim2_new(1, 0, 1, -4),
		ScrollBarThickness = 0, CanvasSize = UDim2_new(0, 0, 0, 0), ZIndex = 51, Parent = fill,
	})
	list.Group = group

	local shownCount = 0
	local function heightFor(count)
		return searchHeight + math.max(min(count, maxRows), 1) * ROW + 8
	end

	-- Places matching rows in order (gliding unless instant) and hides the rest.
	local function layoutRows(instant)
		local filter = search and string.lower(search.Text) or ""
		local slot = 0
		for _, row in list.Rows do
			local match = filter == "" or string.find(string.lower(tostring(row.Value)), filter, 1, true) ~= nil
			if match then
				local goal = fromOffset(0, slot * ROW)
				if not row.Button.Visible or instant then
					row.Button.Position = goal
					row.Label.TextTransparency = instant and 0 or 1
					row.Button.Visible = true
					tween(row.Label, { TextTransparency = 0 }, instant and 0 or nil)
				else
					tween(row.Button, { Position = goal })
				end
				slot += 1
			else
				row.Button.Visible = false
			end
		end
		shownCount = slot
		scroll.CanvasSize = UDim2_new(0, 0, 0, slot * ROW)
		return slot
	end

	local width = 100
	local function resize(instant)
		local height = heightFor(shownCount)
		local time = instant and 0 or microTime() * 1.5
		tween(outer, { Size = UDim2_new(1, 0, 0, height - searchHeight) }, time)
		if list.Open then tween(group, { Size = fromOffset(width, height) }, time) end
	end

	if search then
		connect(search:GetPropertyChangedSignal("Text"), function()
			if not list.Open then return end
			scroll.CanvasPosition = Vector2.new(0, 0)
			layoutRows(false)
			resize(false)
		end)
	end

	function list:Build(values, isSelected, onPick)
		for _, row in self.Rows do row.Button:Destroy() end
		self.Rows = {}
		for _, value in values do
			local button = create("TextButton", { Name = "Option", BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Size = UDim2_new(1, 0, 0, ROW), ZIndex = 52, Parent = scroll })
			local label = text(button, { Text = tostring(value), Color = false, Truncate = true, Position = fromOffset(5, centerY(ROW)), Size = UDim2_new(1, -10, 0, 12), ZIndex = 52 })
			local row = { Button = button, Label = label, Value = value, Hover = false }
			function row.Paint(time)
				local theme = Pink.Theme
				tween(label, { TextColor3 = isSelected(value) and theme.Accent or (row.Hover and theme.TextColor or theme.Unselected) }, time)
			end
			row.Paint(0)
			connect(button.MouseEnter, function() row.Hover = true; row.Paint() end)
			connect(button.MouseLeave, function() row.Hover = false; row.Paint() end)
			connect(button.MouseButton1Click, function()
				onPick(value)
				self:Repaint()
			end)
			table.insert(self.Rows, row)
		end
		layoutRows(true)
	end
	function list:Repaint(time)
		for _, row in self.Rows do row.Paint(time) end
	end
	paint(function() list:Repaint(0) end)

	local follow
	local function place()
		local anchor = list.Anchor
		if not anchor or not anchor.Parent then return end
		local position = toGui(anchor.AbsolutePosition)
		group.Position = fromOffset(position.X, position.Y + anchor.AbsoluteSize.Y + 3)
	end

	function list:Show(anchor)
		closePopup()
		activePopup = self
		self.Open = true
		self.Anchor = anchor
		width = anchor.AbsoluteSize.X
		if search then search.Text = "" end
		layoutRows(true)
		place()
		if not group.Visible then group.Size = fromOffset(width, 0) end
		group.Visible = true
		resize(false)
		if follow then follow:Disconnect() end
		follow = RunService.RenderStepped:Connect(place)
		owner:_opened(true)
	end
	function list:Close()
		self.Open = false
		if activePopup == self then activePopup = nil end
		if follow then follow:Disconnect(); follow = nil end
		if search then pcall(function() search:ReleaseFocus() end) end
		local t = tween(group, { Size = fromOffset(width, 0) }, microTime() * 1.5)
		local function hide() if not list.Open then group.Visible = false end end
		if t then t.Completed:Connect(hide) else hide() end
		owner:_opened(false)
	end
	return list
end

local function plusIcon(parent, zindex)
	local icon = create("Frame", { Name = "Plus", BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2_new(0.5, 0, 0.5, 0), Size = fromOffset(6, 6), ZIndex = zindex or 2, Parent = parent })
	local h = create("Frame", { Position = fromOffset(0, 2), Size = fromOffset(6, 2), ZIndex = icon.ZIndex, Parent = icon })
	local v = create("Frame", { Position = fromOffset(2, 0), Size = fromOffset(2, 6), ZIndex = icon.ZIndex, Parent = icon })
	paint(function(theme)
		local color = lerpColor(theme.Unselected, theme.Outline, 0.25)
		h.BackgroundColor3, v.BackgroundColor3 = color, color
	end)
	return icon, v
end

function Container:_dropdownBox(parent, position, size)
	local outer, inline, fill = box(parent, { Position = position, Size = size })
	local valueText = text(outer, { Text = "", Color = "Unselected", Truncate = true, Position = fromOffset(6, centerY(BOX_H)), Size = UDim2_new(1, -28, 0, 12), ZIndex = 2 })
	local separator = create("Frame", { Name = "Separator", AnchorPoint = Vector2.new(1, 0), Position = UDim2_new(1, -16, 0, 0), Size = UDim2_new(0, 1, 1, 0), ZIndex = 2, Parent = fill })
	paint(function(theme) separator.BackgroundColor3 = theme.Inline end)
	local plusHolder = create("Frame", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0), Position = UDim2_new(1, 0, 0, 0), Size = UDim2_new(0, 16, 1, 0), ZIndex = 2, Parent = fill })
	local _, plusBar = plusIcon(plusHolder, 2)
	local click = create("TextButton", { Name = "Click", BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Size = UDim2_new(1, 0, 1, 0), ZIndex = 3, Parent = outer })
	return outer, valueText, click, plusBar
end

function Container:Dropdown(options)
	local holder = self:_holder(options.Name == false and BOX_H or DROPDOWN_H, "Dropdown")
	local boxY = DROPDOWN_BOX_Y
	if options.Name == false then boxY = 0 else
		text(holder, { Text = options.Name or "Dropdown", Color = "Unselected", Position = fromOffset(0, glyph(0)) })
	end
	local outer, valueText, click = self:_dropdownBox(holder, fromOffset(0, boxY), UDim2_new(1, 0, 0, BOX_H))

	local element = newElement(options)
	element.Holder, element.Type = holder, "Dropdown"
	element.Values = options.Values or options.Options or {}
	element.Multi = options.Multi == true
	if element.Multi then
		element.Value = {}
		for _, v in (type(options.Default) == "table" and options.Default or { options.Default }) do element.Value[v] = true end
	else
		element.Value = options.Default
	end

	local function display()
		if element.Multi then
			local picked = {}
			for _, v in element.Values do if element.Value[v] then table.insert(picked, tostring(v)) end end
			valueText.Text = #picked > 0 and table.concat(picked, ", ") or "None"
		else
			valueText.Text = element.Value ~= nil and tostring(element.Value) or "None"
		end
	end

	-- The option list lives on the overlay layer, separate from the section and window.
	local list = optionList({ _opened = function(_, open)
		tween(valueText, { TextColor3 = open and Pink.Theme.TextColor or Pink.Theme.Unselected })
	end }, options)
	element.List = list
	local function isSelected(v)
		if element.Multi then return element.Value[v] == true end
		return element.Value == v
	end
	local function rebuild()
		list:Build(element.Values, isSelected, function(v)
			if element.Multi then
				local copy = table.clone(element.Value)
				copy[v] = not copy[v] or nil
				element:Set(copy)
			else
				element:Set(v)
				list:Close()
			end
		end)
	end

	function element:Set(value)
		if self.Multi then
			if type(value) ~= "table" then value = { [value] = true } end
			local normal = {}
			for k, v in value do
				if type(k) == "number" then normal[v] = true elseif v then normal[k] = true end
			end
			self.Value = normal
		else
			if value == self.Value then return end
			self.Value = value
		end
		display()
		list:Repaint()
		fire(self, self.Value)
	end
	function element:Get() return self.Value end
	function element:SetValues(values)
		self.Values = values
		if list.Open then rebuild() end
		display()
	end
	element.Refresh = element.SetValues
	function element:Close() if list.Open then list:Close() end end

	connect(click.MouseButton1Click, function()
		if list.Open then list:Close() else
			rebuild()
			list:Show(outer, #element.Values)
		end
	end)
	connect(click.MouseEnter, function() if not list.Open then tween(valueText, { TextColor3 = Pink.Theme.TextColor }) end end)
	connect(click.MouseLeave, function() if not list.Open then tween(valueText, { TextColor3 = Pink.Theme.Unselected }) end end)

	display()
	return register(element, options)
end

-- Inline list box (always open) -----------------------------------------------------
function Container:List(options)
	local rows = options.Rows or #(options.Values or {})
	local height = options.Height or (rows * 15 + 8)
	local holder = self:_holder(height, "List")
	local outer, inline, fill = box(holder, { Size = UDim2_new(1, 0, 1, 0) })
	local scroll = create("ScrollingFrame", { Name = "Rows", BackgroundTransparency = 1, Position = fromOffset(0, options.PaddingTop or 3), Size = UDim2_new(1, 0, 1, -(options.PaddingTop or 3) - 2), ScrollBarThickness = 0, CanvasSize = UDim2_new(0, 0, 0, 0), Parent = fill })
	create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Parent = scroll })
	local rowHeight = options.RowHeight or 15

	local element = newElement(options)
	element.Holder, element.Type, element.Rows = holder, "List", {}
	local rowData = setmetatable({}, { __mode = "k" })
	element.Values = options.Values or {}
	element.Multi = options.Multi == true
	element.Value = element.Multi and {} or options.Default
	if element.Multi then for _, v in (type(options.Default) == "table" and options.Default or { options.Default }) do element.Value[v] = true end end

	local function selected(v) if element.Multi then return element.Value[v] == true end return element.Value == v end
	local function paintRows()
		for _, row in element.Rows do
			local theme = Pink.Theme
			local data = rowData[row]
			data.Label.TextColor3 = selected(data.Value) and theme.Accent or (data.Hover and theme.TextColor or theme.Unselected)
		end
	end
	paint(paintRows)

	function element:SetValues(values)
		for _, row in self.Rows do row:Destroy() end
		self.Rows = {}
		self.Values = values
		for index, value in values do
			local row = create("TextButton", { Name = "Row", BackgroundTransparency = 1, Text = "", AutoButtonColor = false, LayoutOrder = index, Size = UDim2_new(1, 0, 0, rowHeight), ZIndex = 2, Parent = scroll })
			local inset = options.TextX or 6
			local label = text(row, { Text = tostring(value), Color = false, Truncate = true, Position = fromOffset(inset, centerY(rowHeight)), Size = UDim2_new(1, -inset * 2, 0, 12), ZIndex = 2 })
			rowData[row] = { Value = value, Hover = false, Label = label }
			connect(row.MouseEnter, function() rowData[row].Hover = true; paintRows() end)
			connect(row.MouseLeave, function() rowData[row].Hover = false; paintRows() end)
			connect(row.MouseButton1Click, function()
				if element.Multi then
					local copy = table.clone(element.Value)
					copy[value] = not copy[value] or nil
					element:Set(copy)
				else
					element:Set(value)
				end
			end)
			table.insert(self.Rows, row)
		end
		scroll.CanvasSize = UDim2_new(0, 0, 0, #values * rowHeight)
		paintRows()
	end
	function element:Set(value)
		if self.Multi then
			local normal = {}
			for k, v in (type(value) == "table" and value or { value }) do
				if type(k) == "number" then normal[v] = true elseif v then normal[k] = true end
			end
			self.Value = normal
		else
			self.Value = value
		end
		paintRows()
		fire(self, self.Value)
	end
	function element:Get() return self.Value end
	element.Refresh = element.SetValues
	element.Scroll, element.Box = scroll, outer

	element:SetValues(element.Values)
	return register(element, options)
end

-- Button --------------------------------------------------------------------------
function Container:Button(options)
	if type(options) == "string" then options = { Name = options } end
	local holder = self:_holder(options.Height or BOX_H, "Button")
	local row = create("Frame", { Name = "Row", BackgroundTransparency = 1, Size = UDim2_new(1, 0, 1, 0), Parent = holder })
	local element = newElement(options)
	element.Holder, element.Type, element.Buttons = holder, "Button", {}

	local function layout()
		local count = #element.Buttons
		local total = row.AbsoluteSize.X
		if total <= 0 then total = self.Width or 200 end
		local x = 0
		for index, b in element.Buttons do
			local width = index == count and (total - x) or math.ceil((total - PAD * (count - 1)) / count)
			b.Position = fromOffset(x, 0)
			b.Size = UDim2_new(0, width, 1, 0)
			for _, child in b:GetChildren() do recenter(child) end
			x += width + PAD
		end
	end

	function element:AddButton(opts)
		if type(opts) == "string" then opts = { Name = opts } end
		local outer = box(row, { Size = UDim2_new(0, 0, 1, 0) })
		local label = text(outer, { Text = opts.Name or "Button", Color = false, CenterX = true, Position = fromOffset(0, centerY(holder.Size.Y.Offset)), ZIndex = 2 })
		local click = create("TextButton", { Name = "Click", BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Size = UDim2_new(1, 0, 1, 0), ZIndex = 3, Parent = outer })
		local hovering, flash = false, false
		local function color(time)
			local theme = Pink.Theme
			tween(label, { TextColor3 = flash and theme.Accent or (hovering and theme.TextColor or theme.Unselected) }, time)
		end
		paint(function() color(0) end)
		connect(click.MouseEnter, function() hovering = true; color(0.15) end)
		connect(click.MouseLeave, function() hovering = false; color(0.15) end)
		connect(click.MouseButton1Click, function()
			flash = true
			color(0.1)
			task.delay(0.25, function() flash = false; color() end)
			if opts.Callback then task.spawn(opts.Callback) end
		end)
		table.insert(self.Buttons, outer)
		outer.Name = opts.Name or "Button"
		layout()
		return self
	end

	relayouts[row] = layout
	element:AddButton(options)
	return element
end

function Container:Buttons(list)
	local first = table.remove(list, 1)
	local element = self:Button(first)
	for _, opts in list do element:AddButton(opts) end
	return element
end

-- Textbox --------------------------------------------------------------------------
function Container:Textbox(options)
	options = options or {}
	local hasLabel = options.Name ~= nil and options.Name ~= false
	local holder = self:_holder(hasLabel and (TEXTBOX_H + 15) or TEXTBOX_H, "Textbox")
	if hasLabel then text(holder, { Text = options.Name, Color = "Unselected", Position = fromOffset(0, glyph(0)) }) end
	local outer = box(holder, { Position = fromOffset(0, hasLabel and 15 or 0), Size = UDim2_new(1, 0, 0, options.Height or TEXTBOX_H), Fill = "reverse" })
	local input = text(outer, { Box = true, Placeholder = options.Placeholder or "", Text = options.Default or "", Color = "Unselected", Position = fromOffset(6, centerY(options.Height or TEXTBOX_H)), Size = UDim2_new(1, -12, 0, 12), ZIndex = 3 })
	input.ClipsDescendants = true
	focusOnClick(outer, input)

	local element = newElement(options)
	element.Holder, element.Type, element.Box = holder, "Textbox", input
	element.Value = input.Text
	function element:Set(value)
		input.Text = tostring(value)
	end
	function element:Get() return self.Value end
	connect(input:GetPropertyChangedSignal("Text"), function()
		element.Value = input.Text
		if not options.Finished then fire(element, input.Text) end
	end)
	connect(input.Focused, function() tween(input, { TextColor3 = Pink.Theme.TextColor }, 0.15) end)
	connect(input.FocusLost, function(enter)
		tween(input, { TextColor3 = Pink.Theme.Unselected }, 0.15)
		if options.Finished then fire(element, input.Text, enter) end
	end)
	return register(element, options)
end
Container.Input = Container.Textbox

-- Keybind --------------------------------------------------------------------------
local binding -- the keybind currently waiting for a key

function Container:_keyBox(parent, options)
	local outer = box(parent, { Size = fromOffset(options.Width or 52, 16), Name = "Keybind" })
	local label = text(outer, { Text = "", Color = "Unselected", CenterX = true, Position = fromOffset(0, centerY(16) - 1), ZIndex = 2 })
	local click = create("TextButton", { Name = "Click", BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Size = UDim2_new(1, 0, 1, 0), ZIndex = 3, Parent = outer })

	local element = newElement(options)
	element.Type = "Keybind"
	element.Value = options.Default
	element.Mode = options.Mode or "Toggle"
	element.Active = element.Mode == "Always"
	element.Label = label
	local modes = { "Toggle", "Hold", "Always" }

	local function display()
		label.Text = binding == element and "..." or keyName(element.Value)
	end
	function element:Set(key, mode)
		if type(key) == "string" then key = Enum.KeyCode[key] or Enum.UserInputType[key] end
		self.Value = key
		if mode then self.Mode = mode end
		display()
		if options.ChangedCallback then task.spawn(options.ChangedCallback, key) end
	end
	function element:Get() return self.Value end
	function element:IsActive() return self.Active end

	connect(click.MouseButton1Click, function()
		binding = element
		display()
		tween(label, { TextColor3 = Pink.Theme.Accent }, 0.15)
	end)
	connect(click.MouseButton2Click, function()
		local index = table.find(modes, element.Mode) or 1
		element.Mode = modes[index % #modes + 1]
		element.Active = element.Mode == "Always"
		label.Text = element.Mode
		task.delay(0.8, display)
	end)

	connect(UserInputService.InputBegan, function(input, processed)
		local pressed = input.KeyCode ~= Enum.KeyCode.Unknown and input.KeyCode or input.UserInputType
		if binding == element then
			if input.UserInputType == Enum.UserInputType.MouseMovement then return end
			if input.UserInputType == Enum.UserInputType.MouseButton1 then return end
			binding = nil
			if input.KeyCode == Enum.KeyCode.Escape or input.KeyCode == Enum.KeyCode.Backspace then
				element:Set(nil)
			else
				element:Set(pressed)
			end
			tween(label, { TextColor3 = Pink.Theme.Unselected }, 0.15)
			return
		end
		if processed or element.Value == nil or pressed ~= element.Value then return end
		if element.Mode == "Toggle" then
			element.Active = not element.Active
			fire(element, element.Active)
		elseif element.Mode == "Hold" then
			element.Active = true
			fire(element, true)
		end
	end)
	connect(UserInputService.InputEnded, function(input)
		local released = input.KeyCode ~= Enum.KeyCode.Unknown and input.KeyCode or input.UserInputType
		if element.Mode == "Hold" and element.Value ~= nil and released == element.Value and element.Active then
			element.Active = false
			fire(element, false)
		end
	end)

	display()
	element.Box = outer
	return register(element, options)
end

function Container:Keybind(options)
	local holder = self:_holder(KEYBIND_H, "Keybind")
	text(holder, { Text = options.Name or "Keybind", Color = "Unselected", Position = fromOffset(0, glyph(3)), Size = UDim2_new(1, -60, 0, 12) })
	local element = self:_keyBox(holder, options)
	element.Box.AnchorPoint = Vector2.new(1, 0)
	element.Box.Position = UDim2_new(1, 0, 0, 2)
	element.Holder = holder
	return element
end

-- Colour picker ---------------------------------------------------------------------
local pickerWindow -- one shared popup

-- 4x4 checkerboard (2px cells) for transparency previews.
local CHECKER_PNG = "iVBORw0KGgoAAAANSUhEUgAAAAQAAAAECAIAAAAmkwkpAAAAIUlEQVR42mN8/fo1AwPD3bt3GRgYmBiQAAtETFlZGV0GAEJ3CGJDCMiLAAAAAElFTkSuQmCC"
local checkerAsset
local function checker(parent, zindex)
	if checkerAsset == nil then
		checkerAsset = false
		pcall(function()
			assert(writefile and getcustomasset and isfolder and makefolder)
			if not isfolder(Pink.Folder) then makefolder(Pink.Folder) end
			local path = Pink.Folder .. "/checker-v1.png"
			writefile(path, base64Decode(CHECKER_PNG))
			checkerAsset = getcustomasset(path)
		end)
	end
	local image = create("ImageLabel", { Name = "Checker", BackgroundColor3 = Color3.fromRGB(218, 218, 218), Image = checkerAsset or "", Size = UDim2_new(1, 0, 1, 0), ZIndex = zindex, Parent = parent })
	pcall(function()
		image.ScaleType = Enum.ScaleType.Tile
		image.TileSize = UDim2.fromOffset(4, 4)
		image.ResampleMode = Enum.ResamplerMode.Pixelated
	end)
	return image
end

-- Handle used on the hue and transparency bars: black outline, translucent dark middle.
local function barHandle(parent, horizontal, zindex)
	local handle = create("Frame", { Name = "Handle", BackgroundColor3 = Color3.new(0, 0, 0), ZIndex = zindex, Parent = parent })
	if horizontal then
		handle.AnchorPoint = Vector2.new(0.5, 0)
		handle.Size = UDim2_new(0, 4, 1, 2)
		handle.Position = UDim2_new(0, 0, 0, -1)
	else
		handle.AnchorPoint = Vector2.new(0, 0.5)
		handle.Size = UDim2_new(1, 2, 0, 4)
		handle.Position = UDim2_new(0, -1, 0, 0)
	end
	create("Frame", { Name = "Middle", BackgroundColor3 = Color3.fromRGB(20, 20, 22), BackgroundTransparency = 0.45, Position = fromOffset(1, 1), Size = UDim2_new(1, -2, 1, -2), ZIndex = zindex, Parent = handle })
	return handle
end

-- Picker layout, measured from the original at native size: 201 x 201, a 160px square with a hue
-- bar to its right and a transparency bar below, plus a preview in the corner.
local PICKER = 201
local function buildPicker()
	if pickerWindow then return pickerWindow end
	local popup = { Open = false }
	local group = create("Frame", { Name = "ColorPicker", BackgroundTransparency = 1, ClipsDescendants = true, Visible = false, Size = fromOffset(PICKER, 0), ZIndex = 60, Parent = Pink.Overlay })
	local outer, inline, fill = box(group, { Size = fromOffset(PICKER, PICKER), Fill = "none", ZIndex = 60 })
	paint(function(theme) fill.BackgroundColor3 = lerpColor(theme.OtherBackground, theme.Outline, 0.2) end)
	-- Child coordinates below are relative to the fill, which starts 2px inside the outline.
	local function at(x) return x - 2 end

	local svOuter, _, svFill = box(fill, { Position = fromOffset(at(6), at(6)), Size = fromOffset(164, 164), Fill = "none", ZIndex = 61 })
	svFill.BackgroundColor3 = Color3.new(1, 0, 0)
	local white = create("Frame", { Name = "White", BackgroundColor3 = Color3.new(1, 1, 1), Size = UDim2_new(1, 0, 1, 0), ZIndex = 62, Parent = svFill })
	create("UIGradient", { Transparency = NumberSequence.new(0, 1), Parent = white })
	local black = create("Frame", { Name = "Black", BackgroundColor3 = Color3.new(0, 0, 0), Size = UDim2_new(1, 0, 1, 0), ZIndex = 63, Parent = svFill })
	create("UIGradient", { Rotation = 90, Transparency = NumberSequence.new(1, 0), Parent = black })
	local cursor = create("Frame", { Name = "Cursor", AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = Color3.new(0, 0, 0), Size = fromOffset(5, 5), ZIndex = 64, Parent = svFill })
	create("Frame", { Name = "Middle", BackgroundColor3 = Color3.new(1, 1, 1), Position = fromOffset(1, 1), Size = fromOffset(3, 3), ZIndex = 64, Parent = cursor })

	local hueOuter, _, hueFill = box(fill, { Position = fromOffset(at(177), at(6)), Size = fromOffset(18, 164), Fill = "none", ZIndex = 61 })
	hueFill.BackgroundColor3 = Color3.new(1, 1, 1)
	local keys = {}
	for i = 0, 6 do table.insert(keys, ColorSequenceKeypoint.new(i / 6, Color3.fromHSV((i / 6) % 1, 1, 1))) end
	create("UIGradient", { Rotation = 90, Color = ColorSequence.new(keys), Parent = hueFill })
	local hueHandle = barHandle(hueFill, false, 64)

	local alphaOuter, _, alphaFill = box(fill, { Position = fromOffset(at(6), at(177)), Size = fromOffset(164, 18), Fill = "none", ZIndex = 61 })
	checker(alphaFill, 62)
	local alphaColor = create("Frame", { Name = "Color", BackgroundColor3 = Color3.new(1, 1, 1), Size = UDim2_new(1, 0, 1, 0), ZIndex = 63, Parent = alphaFill })
	create("UIGradient", { Transparency = NumberSequence.new(1, 0), Parent = alphaColor })
	local alphaHandle = barHandle(alphaFill, true, 64)

	local previewOuter, _, previewFill = box(fill, { Position = fromOffset(at(177), at(177)), Size = fromOffset(18, 18), Fill = "none", ZIndex = 61 })
	checker(previewFill, 62)
	local preview = create("Frame", { Name = "Color", Size = UDim2_new(1, 0, 1, 0), ZIndex = 63, Parent = previewFill })

	local h, s, v, a = 0, 1, 1, 0
	popup.Group = group
	-- Handles glide to their spot; dragging keeps them under the cursor.
	local function sync(push, instant)
		local color = Color3.fromHSV(h, s, v)
		svFill.BackgroundColor3 = Color3.fromHSV(h, 1, 1)
		alphaColor.BackgroundColor3 = color
		preview.BackgroundColor3 = color
		preview.BackgroundTransparency = a
		local time = instant and 0 or 0.08
		tween(cursor, { Position = UDim2_new(s, 0, 1 - v, 0) }, time)
		tween(hueHandle, { Position = UDim2_new(0, -1, h, 0) }, time)
		tween(alphaHandle, { Position = UDim2_new(1 - a, 0, 0, -1) }, time)
		if push and popup.Target then popup.Target:Set(color, a) end
	end
	popup.Sync = sync

	local function dragArea(outerBox, onMove)
		local hit = create("TextButton", { BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Size = UDim2_new(1, 0, 1, 0), ZIndex = 65, Parent = outerBox })
		connect(hit.InputBegan, function(input)
			if isClick(input) then beginDrag(onMove) end
		end)
	end
	dragArea(svOuter, function(point)
		s = clamp((point.X - svFill.AbsolutePosition.X) / svFill.AbsoluteSize.X, 0, 1)
		v = 1 - clamp((point.Y - svFill.AbsolutePosition.Y) / svFill.AbsoluteSize.Y, 0, 1)
		sync(true)
	end)
	dragArea(hueOuter, function(point)
		h = clamp((point.Y - hueFill.AbsolutePosition.Y) / hueFill.AbsoluteSize.Y, 0, 0.999)
		sync(true)
	end)
	dragArea(alphaOuter, function(point)
		a = 1 - clamp((point.X - alphaFill.AbsolutePosition.X) / alphaFill.AbsoluteSize.X, 0, 1)
		sync(true)
	end)

	local follow
	function popup:Show(target, anchor)
		closePopup()
		activePopup = self
		self.Open = true
		self.Target = target
		self.Anchor = anchor
		h, s, v = toHSV(target.Value)
		a = target.Transparency or 0
		sync(false, true)
		-- Opens below the swatch, left edges aligned, as in the original; flips to stay on screen.
		local function place()
			local position = toGui(anchor.AbsolutePosition)
			local screen = Pink.Gui.AbsoluteSize
			local x, y = position.X, position.Y + anchor.AbsoluteSize.Y + 2
			if screen.X > 0 and x + PICKER > screen.X - 4 then x = position.X + anchor.AbsoluteSize.X - PICKER end
			if screen.Y > 0 and y + PICKER > screen.Y - 4 then y = position.Y - PICKER - 2 end
			group.Position = fromOffset(floor(x), floor(y))
		end
		place()
		if follow then follow:Disconnect() end
		follow = RunService.RenderStepped:Connect(place)
		group.Visible = true
		tween(group, { Size = fromOffset(PICKER, PICKER) }, microTime() * 1.5)
	end
	function popup:Close()
		self.Open = false
		self.Target = nil
		if activePopup == self then activePopup = nil end
		if follow then follow:Disconnect(); follow = nil end
		local t = tween(group, { Size = fromOffset(PICKER, 0) }, microTime() * 1.5)
		local function hide() if not self.Open then group.Visible = false end end
		if t then t.Completed:Connect(hide) else hide() end
	end

	pickerWindow = popup
	return popup
end

function Container:_colorSwatch(parent, options)
	local outer, inline, fill = box(parent, { Size = fromOffset(23, 14), Name = "Swatch", Fill = "none" })
	checker(fill, 1)
	local color = create("Frame", { Name = "Color", BackgroundColor3 = Color3.new(1, 1, 1), Size = UDim2_new(1, 0, 1, 0), ZIndex = 1, Parent = fill })
	create("UIGradient", { Rotation = 90, Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(205, 205, 205)), Parent = color })
	local click = create("TextButton", { Name = "Click", BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Size = UDim2_new(1, 0, 1, 0), ZIndex = 3, Parent = outer })

	local element = newElement(options)
	element.Type = "Colorpicker"
	element.Value = options.Default or Color3.new(1, 1, 1)
	element.Transparency = options.Transparency or 0
	element.Swatch = outer
	local function display()
		color.BackgroundColor3 = element.Value
		color.BackgroundTransparency = element.Transparency
	end
	element.Repaint = display

	function element:Set(value, transparency)
		if typeof(value) == "string" then value = fromHex(value) or self.Value end
		if typeof(value) == "table" then value = Color3.new(value[1], value[2], value[3]) end
		self.Value = value
		if transparency then self.Transparency = transparency end
		display()
		fire(self, value, self.Transparency)
	end
	function element:Get() return self.Value end
	element.SetValueRGB = element.Set

	connect(click.MouseButton1Click, function()
		local popup = buildPicker()
		if popup.Open and popup.Target == element then popup:Close() else popup:Show(element, outer) end
	end)

	display()
	return register(element, options)
end

function Container:Colorpicker(options)
	local holder = self:_holder(COLOR_H, "Colorpicker")
	text(holder, { Text = options.Name or "Colorpicker", Color = "Unselected", Position = fromOffset(0, glyph(3)), Size = UDim2_new(1, -30, 0, 12) })
	local element = self:_colorSwatch(holder, options)
	element.Swatch.AnchorPoint = Vector2.new(1, 0)
	element.Swatch.Position = UDim2_new(1, 0, 0, 2)
	element.Holder = holder
	return element
end
Container.ColorPicker = Container.Colorpicker

-- Section -------------------------------------------------------------------------------
local Section = setmetatable({}, { __index = Container })
Section.__index = Section

local function newSection(parentFrame, name, width, column)
	local outer, inline, fill = box(parentFrame, { Name = "Section", Size = fromOffset(width, 100), Fill = "none" })
	fill.BackgroundColor3 = Color3.new(1, 1, 1)
	local gradient = create("UIGradient", { Rotation = 90, Parent = fill })
	-- Accent bar: outline row, accent row, darker accent row, outline row.
	local bar = create("Frame", { Name = "Accent", Position = fromOffset(1, 1), Size = UDim2_new(1, -2, 0, 3), Parent = outer })
	local barDim = create("Frame", { Name = "Dim", Position = fromOffset(0, 1), Size = UDim2_new(1, 0, 0, 1), Parent = bar })
	local barLine = create("Frame", { Name = "Line", Position = fromOffset(0, 2), Size = UDim2_new(1, 0, 0, 1), Parent = bar })
	paint(function(theme)
		gradient.Color = ColorSequence.new(theme.SectionBackground, theme.LowContrast)
		bar.BackgroundColor3 = theme.Accent
		barDim.BackgroundColor3 = lerpColor(theme.Accent, theme.Outline, 0.5)
		barLine.BackgroundColor3 = theme.Outline
	end)
	local title = text(outer, { Text = name or "Section", Color = "TextColor", Position = fromOffset(9, glyph(13)), Size = UDim2_new(1, -18, 0, 12) })

	local body = create("ScrollingFrame", {
		Name = "Body", BackgroundTransparency = 1, Position = fromOffset(2, SECTION_BODY_Y), Size = UDim2_new(1, -4, 1, -(SECTION_BODY_Y + 2)),
		ScrollBarThickness = 0, CanvasSize = UDim2_new(0, 0, 0, 0), Parent = outer,
	})
	local self = newContainer(body, -12, nil)
	self.Width = width - 16
	setmetatable(self, Section)
	self.Frame.Position = fromOffset(6, SECTION_TOP - SECTION_BODY_Y)
	self.Root, self.Body, self.Title, self.Column = outer, body, title, column
	self.MaxHeight = math.huge
	self.Owner = {
		Resize = function()
			body.CanvasSize = UDim2_new(0, 0, 0, SECTION_TOP - SECTION_BODY_Y + self:ContentHeight() + SECTION_BOTTOM - 2)
			if self.Column then self.Column:Fit() else self:SetHeight(self:NaturalHeight()) end
		end,
	}
	return self
end

function Section:NaturalHeight()
	return SECTION_TOP + self:ContentHeight() + SECTION_BOTTOM
end

function Section:SetHeight(height)
	self.Root.Size = fromOffset(self.Root.Size.X.Offset, height)
end

-- A column stacks sections and shrinks the tallest ones when they overflow.
local function newColumn(frame, height)
	local column = { Frame = frame, Height = height, Sections = {}, Gap = 8 }
	function column:Fit()
		local count = #self.Sections
		if count == 0 then return end
		local available = self.Height - self.Gap * (count - 1)
		local natural, sizes, fixed = {}, {}, {}
		for i, section in self.Sections do natural[i] = section:NaturalHeight() end
		local remaining, open = available, count
		local changed = true
		while changed do
			changed = false
			local share = remaining / max(open, 1)
			for i = 1, count do
				if not fixed[i] and natural[i] <= share then
					fixed[i], sizes[i] = true, natural[i]
					remaining -= natural[i]
					open -= 1
					changed = true
				end
			end
		end
		local share = open > 0 and floor(remaining / open) or 0
		local y = 0
		for i, section in self.Sections do
			local height = fixed[i] and sizes[i] or share
			section.Root.Position = fromOffset(0, y)
			section:SetHeight(height)
			y += height + self.Gap
		end
	end
	return column
end

-- Tabs -------------------------------------------------------------------------------------
local Tab = {}
Tab.__index = Tab

function Tab:Section(name, side)
	if type(name) == "table" then name, side = name.Name, name.Side end
	local column = (side == "Right" or side == 2) and self.Right or self.Left
	local section = newSection(column.Frame, name, self.ColumnWidth, column)
	table.insert(column.Sections, section)
	section.Owner.Resize()
	return section
end
Tab.AddSection = Tab.Section
function Tab:LeftSection(name) return self:Section(name, "Left") end
function Tab:RightSection(name) return self:Section(name, "Right") end

-- Windows ------------------------------------------------------------------------------------
local function ensureGui()
	if Pink.Gui then return Pink.Gui end
	Pink:LoadFonts()
	local gui = create("ScreenGui", { Name = "Pink", ResetOnSpawn = false, IgnoreGuiInset = true, ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 100 })
	local parent
	pcall(function() if gethui then parent = gethui() end end)
	if not parent and CoreGui then pcall(function() local test = CoreGui.Name; parent = CoreGui end) end
	if not parent and LocalPlayer then parent = LocalPlayer:WaitForChild("PlayerGui") end
	local ok = pcall(function() gui.Parent = parent end)
	if not ok and LocalPlayer then gui.Parent = LocalPlayer:WaitForChild("PlayerGui") end
	Pink.Gui = gui
	Pink:_detectTextSize(gui)
	Pink.Holder = create("Frame", { Name = "Windows", BackgroundTransparency = 1, Size = UDim2_new(1, 0, 1, 0), Parent = gui })
	Pink.Overlay = create("Frame", { Name = "Overlay", BackgroundTransparency = 1, Size = UDim2_new(1, 0, 1, 0), ZIndex = 50, Parent = gui })
	Pink.NotifyHolder = create("Frame", { Name = "Notifications", BackgroundTransparency = 1, Position = fromOffset(20, 60), Size = fromOffset(400, 600), ZIndex = 80, Parent = gui })

	-- Clicking outside an open popup closes it.
	connect(UserInputService.InputBegan, function(input)
		if not isClick(input) or not activePopup then return end
		local popup = activePopup
		local point = mousePosition()
		task.defer(function()
			if activePopup == popup and not inside(popup.Group, point) then
				local anchorHit = false
				if popup.Anchor and inside(popup.Anchor, point) then anchorHit = true end
				if not anchorHit then closePopup() end
			end
		end)
	end)
	-- Menu bind.
	connect(UserInputService.InputBegan, function(input, processed)
		if processed or binding or not Pink.ToggleKey then return end
		local key = Pink.ToggleKey
		if type(key) == "table" then key = key.Value end
		if key and (input.KeyCode == key or input.UserInputType == key) then Pink:Toggle() end
	end)
	return gui
end

local zCounter = 1
local function makeWindow(options)
	ensureGui()
	local size = options.Size or Vector2.new(520, 642)
	local root = create("Frame", { Name = options.Name or "Window", BackgroundTransparency = 1, Position = fromOffset(options.Position and options.Position.X or 100, options.Position and options.Position.Y or 100), Size = fromOffset(size.X, size.Y), Parent = Pink.Holder })
	local outer, inline, fill = box(root, { Size = UDim2_new(1, 0, 1, 0), Fill = "OtherBackground" })
	local window = { Root = root, Frame = fill, Outer = outer, Size = size }

	-- Drag from the title strip.
	local drag = create("TextButton", { Name = "Drag", BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Size = UDim2_new(1, 0, 0, 30), Parent = outer })
	connect(drag.InputBegan, function(input)
		if not isClick(input) then return end
		zCounter += 1
		root.ZIndex = zCounter
		local start, origin = mousePosition(), root.Position
		beginDrag(function(point)
			local delta = point - start
			root.Position = UDim2_new(origin.X.Scale, origin.X.Offset + delta.X, origin.Y.Scale, origin.Y.Offset + delta.Y)
		end)
	end)
	connect(root.InputBegan, function(input)
		if isClick(input) then zCounter += 1; root.ZIndex = zCounter end
	end)
	table.insert(Pink.Windows, window)
	return window
end

local function panelTitle(window, name, x)
	text(window.Outer, { Text = name, Bold = true, Color = "Accent", Position = fromOffset(x, glyph(11)), Size = fromOffset(300, 12), ZIndex = 2 })
end

-- Cherry drawn from frames so the library needs no uploaded image.
local function cherryIcon(parent)
	local icon = create("Frame", { Name = "Icon", BackgroundTransparency = 1, Position = fromOffset(9, 5), Size = fromOffset(20, 20), Parent = parent })
	local function dot(x, y, size, color, name)
		local frame = create("Frame", { Name = name, Position = fromOffset(x, y), Size = fromOffset(size, size), BackgroundColor3 = color, Parent = icon })
		create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = frame })
		return frame
	end
	local pixels = { { 10, 3 }, { 9, 4 }, { 8, 5 }, { 7, 6 }, { 6, 7 }, { 6, 8 }, { 5, 9 }, { 11, 4 }, { 11, 5 }, { 12, 6 }, { 12, 7 }, { 13, 8 }, { 13, 9 } }
	for _, p in pixels do
		create("Frame", { Name = "Stem", Position = fromOffset(p[1], p[2]), Size = fromOffset(1, 1), BackgroundColor3 = Color3.fromRGB(96, 52, 40), Parent = icon })
	end
	create("Frame", { Name = "Leaf", Position = fromOffset(11, 1), Size = fromOffset(6, 3), BackgroundColor3 = Color3.fromRGB(70, 150, 90), Parent = icon })
	create("Frame", { Name = "Leaf", Position = fromOffset(12, 0), Size = fromOffset(3, 1), BackgroundColor3 = Color3.fromRGB(110, 190, 120), Parent = icon })
	local left = dot(1, 9, 9, Color3.fromRGB(232, 112, 150), "Cherry")
	local right = dot(9, 10, 9, Color3.fromRGB(240, 128, 160), "Cherry")
	dot(3, 11, 3, Color3.fromRGB(255, 205, 220), "Shine")
	dot(11, 12, 3, Color3.fromRGB(255, 210, 225), "Shine")
	return icon
end

function Pink:Window(options)
	options = options or {}
	local window = makeWindow({ Name = options.Name or "Pink", Size = options.Size or Vector2.new(520, 642), Position = Vector2.new(0, 0) })
	setmetatable(window, { __index = Pink.WindowMethods })
	window.Tabs = {}
	local size = window.Size

	if options.Icon then
		create("ImageLabel", { Name = "Icon", BackgroundTransparency = 1, Image = options.Icon, Position = fromOffset(9, 5), Size = fromOffset(20, 20), Parent = window.Outer })
	else
		cherryIcon(window.Outer)
	end
	text(window.Outer, { Text = options.Name or "Pink", Bold = true, Color = "Accent", Position = fromOffset(38, glyph(11)), Size = fromOffset(300, 12), ZIndex = 2 })

	-- Tab strip and page area share one bevelled panel.
	local footerHeight = options.Footer == false and 0 or 34
	window.FooterHeight = footerHeight
	window.MinSize = options.MinSize or Vector2.new(400, 320)
	local contentHeight = size.Y - 30 - 10 - footerHeight
	local content = box(window.Outer, { Name = "Content", Position = fromOffset(10, 30), Size = fromOffset(size.X - 20, contentHeight), Fill = "SectionBackground" })
	local strip = create("Frame", { Name = "Tabs", Position = fromOffset(1, 1), Size = UDim2_new(1, -2, 0, 21), Parent = content })
	local divider = create("Frame", { Name = "Divider", Position = fromOffset(1, 22), Size = UDim2_new(1, -2, 0, 1), Parent = content })
	paint(function(theme)
		strip.BackgroundColor3 = theme.Inline
		divider.BackgroundColor3 = theme.Outline
	end)
	window.Content, window.Strip = content, strip
	window.TabX = 7
	window.Pages = create("Frame", { Name = "Pages", BackgroundTransparency = 1, Position = fromOffset(8, 31), Size = fromOffset(size.X - 36, contentHeight - 39), Parent = content })
	window.ColumnWidth = floor((size.X - 36 - 8) / 2)

	if options.Footer ~= false then
		local footer = box(window.Outer, { Name = "Footer", Position = fromOffset(10, size.Y - 38), Size = fromOffset(size.X - 20, 28), Fill = "SectionBackground" })
		window.Footer = footer
		local footerOptions = type(options.Footer) == "table" and options.Footer or {}
		local userName = footerOptions.User or (LocalPlayer and LocalPlayer.Name) or "player"
		local greeting = text(footer, { Text = footerOptions.Greeting or "welcome back,", Color = "TextColor", Position = fromOffset(9, glyph(9)), Size = fromOffset(200, 12), ZIndex = 2 })
		local user = text(footer, { Text = userName, Bold = true, Color = "Accent", Position = fromOffset(80, glyph(9)), Size = fromOffset(250, 12), ZIndex = 2 })
		onBounds(greeting, function() user.Position = fromOffset(9 + floor(greeting.TextBounds.X) + 5, glyph(9)) end)
		local right = create("Frame", { Name = "Status", BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0), Position = UDim2_new(1, -9, 0, 0), Size = fromOffset(300, 28), Parent = footer })
		local closeB = text(right, { Text = "]", Color = "TextColor", XAlign = Enum.TextXAlignment.Right, Position = UDim2_new(0, 0, 0, glyph(9)), Size = UDim2_new(1, 0, 0, 12), ZIndex = 2 })
		local status = text(right, { Text = "", Bold = true, Color = "Accent", XAlign = Enum.TextXAlignment.Right, Position = UDim2_new(0, 0, 0, glyph(9)), Size = UDim2_new(1, -10, 0, 12), ZIndex = 2 })
		local openB = text(right, { Text = "[", Color = "TextColor", XAlign = Enum.TextXAlignment.Right, Position = UDim2_new(0, 0, 0, glyph(9)), Size = UDim2_new(1, 0, 0, 12), ZIndex = 2 })
		onBounds(status, function() openB.Size = UDim2_new(1, -(10 + floor(status.TextBounds.X) + 7), 0, 12) end)
		function window:SetStatus(value)
			status.Text = value or ""
			openB.Visible = value ~= nil and value ~= ""
			closeB.Visible = openB.Visible
		end
		function window:SetUser(value)
			user.Text = value
		end
		window:SetStatus(footerOptions.Status or footerOptions.Game or "")
	end

	if options.Keybind ~= false then Pink.ToggleKey = options.Keybind or Enum.KeyCode.V end

	-- Side panels, laid out like the reference to the right of the main window.
	if options.Panels ~= false then
		local panels = type(options.Panels) == "table" and options.Panels or { Configurations = true, Appearance = true, Playerlist = true }
		if panels.Configurations then window.ConfigPanel = Pink:ConfigPanel({ Position = Vector2.new(size.X + 10, 0) }) end
		if panels.Appearance then window.AppearancePanel = Pink:AppearancePanel({ Position = Vector2.new(size.X + 260, 0) }) end
		if panels.Playerlist then window.Playerlist = Pink:Playerlist({ Position = Vector2.new(size.X + 10, 290) }) end
	end
	-- Resize grip: accent square over the bottom-right corner.
	if options.Resizable ~= false then
		local grip = create("TextButton", { Name = "ResizeGrip", Text = "", AutoButtonColor = false, AnchorPoint = Vector2.new(1, 1), Position = UDim2_new(1, 0, 1, 0), Size = fromOffset(9, 9), ZIndex = 20, Parent = window.Root })
		paint(function(theme) grip.BackgroundColor3 = theme.Accent end)
		connect(grip.InputBegan, function(input)
			if not isClick(input) then return end
			local start, origin = mousePosition(), window.Size
			beginDrag(function(point)
				local delta = point - start
				window:SetSize(origin.X + delta.X, origin.Y + delta.Y)
			end)
		end)
		window.Grip = grip
	end

	window.Main = window
	window:Center()
	return window
end

Pink.WindowMethods = {}
local WindowMethods = Pink.WindowMethods

-- Resizes the main window and re-flows tabs, columns, sections and footer to fit.
function WindowMethods:SetSize(width, height)
	width = max(self.MinSize.X, floor(width))
	height = max(self.MinSize.Y, floor(height))
	if self.Size.X == width and self.Size.Y == height then return end
	self.Size = Vector2.new(width, height)
	self.Root.Size = fromOffset(width, height)
	local contentHeight = height - 40 - self.FooterHeight
	local columnHeight = contentHeight - 39
	self.Content.Size = fromOffset(width - 20, contentHeight)
	self.Pages.Size = fromOffset(width - 36, columnHeight)
	self.ColumnWidth = floor((width - 44) / 2)
	for _, tab in self.Tabs do
		tab.ColumnWidth = self.ColumnWidth
		for index, column in { tab.Left, tab.Right } do
			column.Frame.Size = fromOffset(self.ColumnWidth, columnHeight)
			if index == 2 then column.Frame.Position = fromOffset(self.ColumnWidth + 8, 0) end
			column.Height = columnHeight
			for _, section in column.Sections do
				section.Width = self.ColumnWidth - 16
				section.Root.Size = fromOffset(self.ColumnWidth, section.Root.Size.Y.Offset)
			end
			column:Fit()
		end
	end
	if self.Footer then
		self.Footer.Position = fromOffset(10, height - 38)
		self.Footer.Size = fromOffset(width - 20, 28)
	end
	for _, fn in relayouts do fn() end
	for _, fn in centerers do fn() end
	if self.OnResize then task.spawn(self.OnResize, width, height) end
end

function WindowMethods:Tab(name)
	local tab = setmetatable({ Name = name, Window = self, ColumnWidth = self.ColumnWidth }, Tab)
	local page = create("Frame", { Name = name, BackgroundTransparency = 1, Size = UDim2_new(1, 0, 1, 0), Visible = false, Parent = self.Pages })
	local columnHeight = self.Pages.Size.Y.Offset
	local leftFrame = create("Frame", { Name = "Left", BackgroundTransparency = 1, Size = fromOffset(self.ColumnWidth, columnHeight), Parent = page })
	local rightFrame = create("Frame", { Name = "Right", BackgroundTransparency = 1, Position = fromOffset(self.ColumnWidth + 8, 0), Size = fromOffset(self.ColumnWidth, columnHeight), Parent = page })
	tab.Page = page
	tab.Left = newColumn(leftFrame, columnHeight)
	tab.Right = newColumn(rightFrame, columnHeight)

	local button = text(self.Strip, { Button = true, Text = name, Bold = true, Color = false, Position = fromOffset(7, glyph(7)), Size = fromOffset(60, 12), ZIndex = 2 })
	tab.Button = button
	onBounds(button, function() self:LayoutTabs() end)
	local hit = create("TextButton", { Name = "Hit", BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Position = fromOffset(-6, -4), Size = UDim2_new(1, 12, 1, 8), ZIndex = 3, Parent = button })

	local hovering = false
	function tab:Paint(time)
		local theme = Pink.Theme
		local active = self.Window.Active == self
		button.FontFace = active and Pink.Fonts.Bold or Pink.Fonts.Regular
		tween(button, { TextColor3 = active and theme.Accent or (hovering and theme.Accent or theme.TextColor) }, time)
	end
	paint(function() tab:Paint(0) end)
	connect(hit.MouseButton1Click, function() self:SelectTab(tab) end)
	connect(hit.MouseEnter, function() hovering = true; tab:Paint(0.15) end)
	connect(hit.MouseLeave, function() hovering = false; tab:Paint(0.15) end)

	table.insert(self.Tabs, tab)
	self:LayoutTabs()
	if not self.Active then self:SelectTab(tab, true) end
	return tab
end
WindowMethods.AddTab = WindowMethods.Tab

function WindowMethods:LayoutTabs()
	local x = 8
	for _, tab in self.Tabs do
		local width = floor(tab.Button.TextBounds.X)
		tab.Button.Position = fromOffset(x, glyph(6))
		tab.Button.Size = fromOffset(width, 12)
		x += width + 12
	end
end

function WindowMethods:SelectTab(tab, instant)
	if self.Active == tab then return end
	closePopup()
	local previous = self.Active
	self.Active = tab
	if previous then
		previous.Page.Visible = false
		previous:Paint(0)
	end
	tab.Page.Visible = true
	tab:Paint(0)
	self:LayoutTabs()
end

-- Composite bounds: main window plus its side panels.
function WindowMethods:Bounds()
	local maxX, maxY = self.Size.X, self.Size.Y
	for _, panel in { self.ConfigPanel, self.AppearancePanel, self.Playerlist } do
		if panel then
			local p = panel.Root.Position
			maxX = max(maxX, p.X.Offset - self.Root.Position.X.Offset + panel.Size.X)
			maxY = max(maxY, p.Y.Offset - self.Root.Position.Y.Offset + panel.Size.Y)
		end
	end
	return maxX, maxY
end

function WindowMethods:Center()
	local viewport = Vector2.new(1920, 1080)
	pcall(function() viewport = workspace.CurrentCamera.ViewportSize end)
	pcall(function() if Pink.Gui.AbsoluteSize.X > 0 then viewport = Pink.Gui.AbsoluteSize end end)
	local w, h = self:Bounds()
	self:MoveTo(floor((viewport.X - w) / 2), floor((viewport.Y - h) / 2))
end

function WindowMethods:MoveTo(x, y)
	local old = self.Root.Position
	local dx, dy = x - old.X.Offset, y - old.Y.Offset
	for _, frame in { self, self.ConfigPanel, self.AppearancePanel, self.Playerlist } do
		if frame then
			local p = frame.Root.Position
			frame.Root.Position = fromOffset(p.X.Offset + dx, p.Y.Offset + dy)
		end
	end
end

-- Generic side panel: a window with a title and one full-size section.
function Pink:Panel(options)
	local size = options.Size or Vector2.new(240, 280)
	local window = makeWindow({ Name = options.Name, Size = size, Position = options.Position })
	panelTitle(window, options.Name or "Panel", 11)
	local area = create("Frame", { Name = "Area", BackgroundTransparency = 1, Position = fromOffset(10, 30), Size = fromOffset(size.X - 20, size.Y - 40), Parent = window.Outer })
	window.Area = area
	function window:Section(name)
		local column = newColumn(area, area.Size.Y.Offset)
		local section = newSection(area, name, area.Size.X.Offset, column)
		column.Sections = { section }
		section.FullHeight = true
		column.Fit = function() section.Root.Position = fromOffset(0, 0); section:SetHeight(area.Size.Y.Offset) end
		section.Owner.Resize()
		return section
	end
	return window
end

-- Configurations ----------------------------------------------------------------------
local function configFolder()
	return Pink.Folder .. "/configs"
end

function Pink:ListConfigs()
	local out = {}
	pcall(function()
		for _, path in listfiles(configFolder()) do
			local name = path:gsub("\\", "/"):match("([^/]+)%.json$")
			if name then table.insert(out, name) end
		end
	end)
	table.sort(out)
	return out
end

function Pink:SaveConfig(name)
	if not name or name == "" then return false, "no name" end
	local data = {}
	for flag, element in self.Flags do
		local value = element.Value
		if element.Type == "Colorpicker" then
			data[flag] = { Type = "Colorpicker", Hex = toHex(value), Transparency = element.Transparency }
		elseif element.Type == "Keybind" then
			data[flag] = { Type = "Keybind", Key = value and value.Name or nil, Mode = element.Mode }
		elseif element.Type == "Dropdown" or element.Type == "List" then
			if element.Multi then
				local list = {}
				for k, on in value do if on then table.insert(list, k) end end
				data[flag] = { Type = element.Type, Value = list }
			else
				data[flag] = { Type = element.Type, Value = value }
			end
		else
			data[flag] = { Type = element.Type, Value = value }
		end
	end
	local ok, err = pcall(function()
		if not isfolder(self.Folder) then makefolder(self.Folder) end
		if not isfolder(configFolder()) then makefolder(configFolder()) end
		writefile(configFolder() .. "/" .. name .. ".json", HttpService:JSONEncode(data))
	end)
	return ok, err
end

function Pink:LoadConfig(name)
	local ok, data = pcall(function() return HttpService:JSONDecode(readfile(configFolder() .. "/" .. name .. ".json")) end)
	if not ok or type(data) ~= "table" then return false, "could not read config" end
	for flag, entry in data do
		local element = self.Flags[flag]
		if element and type(entry) == "table" then
			if entry.Type == "Colorpicker" then
				element:Set(fromHex(entry.Hex) or element.Value, entry.Transparency)
			elseif entry.Type == "Keybind" then
				element:Set(entry.Key and (Enum.KeyCode[entry.Key] or Enum.UserInputType[entry.Key]) or nil, entry.Mode)
			else
				element:Set(entry.Value)
			end
		end
	end
	return true
end

function Pink:DeleteConfig(name)
	return pcall(function() delfile(configFolder() .. "/" .. name .. ".json") end)
end

function Pink:ConfigPanel(options)
	local panel = self:Panel({ Name = "Configurations", Size = Vector2.new(240, 280), Position = options and options.Position })
	local section = panel:Section("Configurations")
	local list = section:List({ Values = self:ListConfigs(), Height = 127, RowHeight = 17, PaddingTop = 6, TextX = 8 })
	local nameBox = section:Textbox({ Placeholder = "" })
	list:OnChanged(function(value) if value then nameBox:Set(value) end end)
	local function refresh() list:SetValues(self:ListConfigs()) end
	section:Buttons({
		{ Name = "Load", Callback = function()
			if list.Value then
				local ok = self:LoadConfig(list.Value)
				self:Notify(ok and ("Loaded config " .. list.Value) or ("Failed to load " .. tostring(list.Value)))
			end
		end },
		{ Name = "Save", Callback = function()
			local name = list.Value or nameBox.Value
			if name and name ~= "" then self:SaveConfig(name); self:Notify("Saved config " .. name); refresh() end
		end },
	})
	section:Buttons({
		{ Name = "Create", Callback = function()
			local name = nameBox.Value
			if name and name ~= "" then self:SaveConfig(name); self:Notify("Created config " .. name); refresh() end
		end },
		{ Name = "Remove", Callback = function()
			if list.Value then self:DeleteConfig(list.Value); self:Notify("Removed config " .. list.Value); list.Value = nil; refresh() end
		end },
	})
	panel.List, panel.NameBox, panel.Refresh = list, nameBox, refresh
	return panel
end

-- Appearance ------------------------------------------------------------------------------------
local easingStyles = { "Linear", "Sine", "Quad", "Cubic", "Quart", "Quint", "Exponential", "Circular", "Back", "Bounce", "Elastic" }

function Pink:AppearancePanel(options)
	local panel = self:Panel({ Name = "Appearance", Size = Vector2.new(240, 280), Position = options and options.Position })
	local section = panel:Section("Overlay & Theme")
	local default = typeof(self.ToggleKey) == "EnumItem" and self.ToggleKey or Enum.KeyCode.V
	local bind = section:Keybind({ Name = "Menu Bind", Default = default, Flag = "Pink_MenuBind" })
	self.ToggleKey = bind
	section:Dropdown({ Name = "Easing Style", Values = easingStyles, Default = self.Tweening.Style, Flag = "Pink_EasingStyle", Callback = function(v) self.Tweening.Style = v end })
	section:Dropdown({ Name = "Easing Direction", Values = { "In", "Out", "InOut" }, Default = self.Tweening.Direction, Flag = "Pink_EasingDirection", Callback = function(v) self.Tweening.Direction = v end })
	section:Slider({ Name = "Tweening Speed", Min = 0, Max = 2, Increment = 0.1, Default = self.Tweening.Speed, Suffix = "s", Flag = "Pink_TweenSpeed", Callback = function(v) self.Tweening.Speed = v end })
	local swatches = {}
	for _, key in self.ThemeOrder do
		swatches[key] = section:Colorpicker({ Name = self.ThemeNames[key], Default = self.Theme[key], Flag = "Pink_Theme_" .. key, Callback = function(color) self:SetTheme(key, color) end })
	end
	-- Keep the swatches in step when code calls SetTheme directly.
	self:OnThemeChanged(function(key, color)
		local swatch = swatches[key]
		if swatch and swatch.Value ~= color then
			swatch.Value = color
			swatch:Repaint()
		end
	end)
	panel.MainSection = section
	return panel
end

-- Player list ------------------------------------------------------------------------------------
function Pink:Playerlist(options)
	options = options or {}
	local size = Vector2.new(490, 360)
	local window = makeWindow({ Name = "Playerlist", Size = size, Position = options.Position })
	panelTitle(window, "Playerlist", 11)
	local content = box(window.Outer, { Name = "Content", Position = fromOffset(10, 30), Size = fromOffset(size.X - 20, size.Y - 40), Fill = "SectionBackground" })
	local area = create("Frame", { Name = "Area", BackgroundTransparency = 1, Position = fromOffset(8, 8), Size = fromOffset(size.X - 36, size.Y - 56), Parent = content })
	local column = newColumn(area, area.Size.Y.Offset)
	local section = newSection(area, "Players", area.Size.X.Offset, column)
	column.Sections = { section }
	column.Fit = function() section:SetHeight(area.Size.Y.Offset) end
	column:Fit()
	local inner = create("Frame", { Name = "Players", BackgroundTransparency = 1, Position = fromOffset(8, SECTION_TOP), Size = fromOffset(section.Width, 264), Parent = section.Root })
	section.Body.Visible = false
	local W = section.Width

	local searchOuter = box(inner, { Size = fromOffset(W, BOX_H), Name = "Search" })
	local search = text(searchOuter, { Box = true, Placeholder = "Search...", Text = "", Color = "Unselected", Position = fromOffset(6, centerY(BOX_H)), Size = UDim2_new(1, -12, 0, 12), ZIndex = 3 })
	focusOnClick(searchOuter, search)
	paint(function(theme) search.PlaceholderColor3 = theme.Unselected end)

	local listOuter, _, listFill = box(inner, { Position = fromOffset(0, 27), Size = fromOffset(W, 110), Name = "List" })
	local scroll = create("ScrollingFrame", { Name = "Rows", BackgroundTransparency = 1, Position = fromOffset(0, 6), Size = UDim2_new(1, 0, 1, -8), ScrollBarThickness = 0, CanvasSize = UDim2_new(0, 0, 0, 0), Parent = listFill })
	create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Parent = scroll })

	local bottom = box(inner, { Position = fromOffset(0, 145), Size = fromOffset(W, 119), Name = "Info" })
	local avatarOuter, _, avatarFill = box(bottom, { Position = fromOffset(7, 8), Size = fromOffset(104, 104), Name = "Avatar" })
	local avatar = create("ImageLabel", { Name = "Headshot", BackgroundTransparency = 1, Image = "", Size = UDim2_new(1, 0, 1, 0), ZIndex = 2, Parent = avatarFill })

	local function bigButton(name, y, callback)
		local outer = box(bottom, { Position = fromOffset(127, y), Size = fromOffset(127, 48), Name = name })
		local label = text(outer, { Text = name, Color = false, CenterX = true, Position = fromOffset(0, centerY(48) - 1), ZIndex = 2 })
		local click = create("TextButton", { BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Size = UDim2_new(1, 0, 1, 0), ZIndex = 3, Parent = outer })
		local hovering = false
		local function color(time) tween(label, { TextColor3 = hovering and Pink.Theme.TextColor or Pink.Theme.Unselected }, time) end
		paint(function() color(0) end)
		connect(click.MouseEnter, function() hovering = true; color(0.15) end)
		connect(click.MouseLeave, function() hovering = false; color(0.15) end)
		connect(click.MouseButton1Click, callback)
		return outer
	end

	local playerlist = { Window = window, Section = section, Selected = nil, Priorities = {}, Rows = {} }
	local priorityLabel = text(bottom, { Text = "Priority", Color = "Unselected", Position = fromOffset(270, glyph(8)), Size = fromOffset(170, 12), Truncate = true, ZIndex = 2 })

	local priorityContainer = { Width = 140, _holder = function() end }
	local priorityOuter, priorityText, priorityClick, priorityPlus = Container._dropdownBox(priorityContainer, bottom, fromOffset(270, 22), fromOffset(140, BOX_H))
	local priorityValues = options.Priorities or { "Neutral", "Friendly", "Enemy", "Priority" }
	priorityText.Text = "Neutral"
	local priorityList = optionList({ _opened = function() end }, { Search = false })

	local function playerName(player) return typeof(player) == "Instance" and player.Name or (type(player) == "table" and player.Name) or tostring(player) end
	local function priorityOf(player) return playerlist.Priorities[playerName(player)] or "Neutral" end

	local function paintRows()
		local theme = Pink.Theme
		for _, row in playerlist.Rows do
			local player = row.Player
			local name = playerName(player)
			local color = row.Hover and lerpColor(theme.TextColor, theme.Accent, 0.5) or theme.TextColor
			if player == LocalPlayer then color = lerpColor(theme.Unselected, theme.Outline, 0.4)
			elseif playerlist.Selected == player then color = theme.Accent
			elseif priorityOf(player) == "Friendly" then color = Color3.fromRGB(120, 200, 140)
			elseif priorityOf(player) == "Enemy" or priorityOf(player) == "Priority" then color = Color3.fromRGB(220, 90, 90) end
			tween(row.Label, { TextColor3 = color })
		end
	end
	paint(paintRows)

	local function select(player)
		playerlist.Selected = player
		priorityLabel.Text = player and playerName(player) or "Priority"
		priorityText.Text = player and priorityOf(player) or "Neutral"
		avatar.Image = ""
		if player and typeof(player) == "Instance" and Players then
			task.spawn(function()
				local ok, image = pcall(function() return Players:GetUserThumbnailAsync(player.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size150x150) end)
				if ok and playerlist.Selected == player then avatar.Image = image end
			end)
		end
		paintRows()
		if options.Callback then task.spawn(options.Callback, player) end
	end

	local function getPlayers()
		if options.GetPlayers then return options.GetPlayers() end
		local ok, list = pcall(function() return Players:GetPlayers() end)
		if ok and type(list) == "table" then return list end
		return { LocalPlayer }
	end

	function playerlist:Refresh()
		for _, row in self.Rows do row.Button:Destroy() end
		self.Rows = {}
		local filter = string.lower(search.Text)
		local all = getPlayers()
		local me = table.find(all, LocalPlayer)
		if me then table.insert(all, 1, table.remove(all, me)) end
		local index = 0
		for _, player in all do
			local name = playerName(player)
			if filter == "" or string.find(string.lower(name), filter, 1, true) then
				index += 1
				local button = create("TextButton", { Name = "Row", BackgroundTransparency = 1, Text = "", AutoButtonColor = false, LayoutOrder = index, Size = UDim2_new(1, 0, 0, ROW_H), ZIndex = 2, Parent = scroll })
				local label = text(button, { Text = name, Color = false, CenterX = true, Position = fromOffset(0, centerY(ROW_H)), ZIndex = 2 })
				local row = { Label = label, Button = button, Player = player }
				connect(button.MouseButton1Click, function()
					if player ~= LocalPlayer then select(playerlist.Selected == player and nil or player) end
				end)
				connect(button.MouseEnter, function() row.Hover = true; paintRows() end)
				connect(button.MouseLeave, function() row.Hover = false; paintRows() end)
				table.insert(self.Rows, row)
			end
		end
		scroll.CanvasSize = UDim2_new(0, 0, 0, index * ROW_H)
		paintRows()
	end

	connect(search:GetPropertyChangedSignal("Text"), function() playerlist:Refresh() end)
	connect(priorityClick.MouseButton1Click, function()
		if priorityList.Open then priorityList:Close() return end
		priorityList:Build(priorityValues, function(v) return priorityText.Text == v end, function(v)
			priorityText.Text = v
			if playerlist.Selected then
				playerlist.Priorities[playerName(playerlist.Selected)] = v
				if options.PriorityCallback then task.spawn(options.PriorityCallback, playerlist.Selected, v) end
			end
			priorityList:Close()
			paintRows()
		end)
		priorityList:Show(priorityOuter, #priorityValues)
	end)

	bigButton("Teleport", 8, function()
		local target = playerlist.Selected
		if not target then return Pink:Notify("Select a player first") end
		if options.Teleport then return options.Teleport(target) end
		pcall(function()
			LocalPlayer.Character:PivotTo(target.Character:GetPivot())
		end)
	end)
	local spectating
	bigButton("Spectate", 64, function()
		local target = playerlist.Selected
		if not target and not spectating then return Pink:Notify("Select a player first") end
		if options.Spectate then return options.Spectate(target) end
		pcall(function()
			local camera = workspace.CurrentCamera
			if spectating == target or not target then
				spectating = nil
				camera.CameraSubject = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
			else
				spectating = target
				camera.CameraSubject = target.Character:FindFirstChildOfClass("Humanoid")
			end
		end)
	end)

	pcall(function()
		connect(Players.PlayerAdded, function() playerlist:Refresh() end)
		connect(Players.PlayerRemoving, function(player)
			if playerlist.Selected == player then select(nil) end
			task.defer(function() playerlist:Refresh() end)
		end)
	end)

	function playerlist:GetPriority(player) return priorityOf(player) end
	function playerlist:SetPriority(player, value) self.Priorities[playerName(player)] = value; paintRows() end
	playerlist.Select = function(_, player) select(player) end
	playerlist.Root, playerlist.Size, playerlist.Search = window.Root, size, search
	playerlist:Refresh()
	return playerlist
end

-- Notifications ------------------------------------------------------------------------------------
local notifications = {}
local function restack()
	local y = 0
	for _, note in notifications do
		if not note.Leaving then
			tween(note.Frame, { Position = fromOffset(note.Frame.Position.X.Offset, y) }, 0.25)
			y += note.Frame.Size.Y.Offset + 8
		end
	end
end

function Pink:Notify(message, duration)
	ensureGui()
	if type(message) == "table" then duration = message.Duration or message.Time; message = message.Text or message.Title or "" end
	duration = duration or 4
	local frame = create("Frame", { Name = "Notification", BackgroundTransparency = 1, Size = fromOffset(120, 37), Parent = self.NotifyHolder })
	local outer = box(frame, { Size = UDim2_new(1, 0, 1, 0), Fill = "OtherBackground" })
	local label = text(outer, { Text = tostring(message), Color = "TextColor", Position = fromOffset(13, centerY(37)), Size = UDim2_new(0, 1000, 0, 12), ZIndex = 2 })
	local width = floor(label.TextBounds.X) + 26
	frame.Size = fromOffset(width, 37)
	label:GetPropertyChangedSignal("TextBounds"):Connect(function()
		width = floor(label.TextBounds.X) + 26
		frame.Size = fromOffset(width, 37)
	end)

	local note = { Frame = frame }
	local y = 0
	for _, other in notifications do if not other.Leaving then y += other.Frame.Size.Y.Offset + 8 end end
	table.insert(notifications, note)
	frame.Position = fromOffset(-width - 20, y)
	fadeAlpha[frame] = 1
	fadeTree(frame, false, Pink.Tweening.Speed)
	styledTween(frame, { Position = fromOffset(0, y) })

	task.delay(duration, function()
		note.Leaving = true
		styledTween(frame, { Position = fromOffset(-width - 20, frame.Position.Y.Offset) })
		fadeTree(frame, true, Pink.Tweening.Speed)
		restack()
		task.delay(Pink.Tweening.Speed + 0.05, function()
			local index = table.find(notifications, note)
			if index then table.remove(notifications, index) end
			frame:Destroy()
		end)
	end)
	return note
end

-- Visibility ------------------------------------------------------------------------------------
function Pink:Toggle(state)
	if state == nil then state = not self.Open end
	if state == self.Open then return end
	self.Open = state
	closePopup()
	local holder = self.Holder
	holder.Visible = true
	fadeTree(holder, not state, self.Tweening.Speed, function()
		if not self.Open then holder.Visible = false end
	end)
end

function Pink:Unload()
	self.Unloaded = true
	for _, connection in self.Connections do pcall(function() connection:Disconnect() end) end
	if self.Gui then self.Gui:Destroy() end
end

function Pink:OnThemeChanged(fn) table.insert(themeListeners, fn) end

if getgenv then getgenv().Pink = Pink end
return Pink
